const PRACTICE_QUESTIONS = [{"topic":"Practice · Resuscitation","question":"A patient with severe pulmonary arterial hypertension and sepsis has MAP 48, dilated failing RV, septal flattening and no fluid responsiveness on passive leg raise. What is the most appropriate initial vasoactive intervention?","options":["Noradrenaline titrated to restore systemic pressure","Rapid infusion of 2 L crystalloid","High-dose dobutamine without vasopressor","Intravenous glyceryl trinitrate"],"answer":0,"explanation":"Noradrenaline restores systemic perfusion and may improve RV coronary perfusion. Excess fluid aggravates RV distension; inotropy can be added once perfusion pressure is supported. Intubation can precipitate RV collapse.","pearl":"Avoid reflexive fluid loading in pressure-overloaded RV failure.","reference":"ESC/ERS pulmonary hypertension guideline; contemporary RV failure reviews","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P001"},{"topic":"Practice · Toxicology","question":"A salicylate-poisoned patient has pH 7.49, PaCO2 19 mmHg, bicarbonate 14 mmol/L, agitation and increasing fatigue. What is the greatest immediate hazard of intubation?","options":["Loss of compensatory minute ventilation may cause rapid acidaemia and CNS salicylate redistribution","Hyperventilation will increase salicylate ionisation","Sedation will immediately increase urinary salicylate clearance","Positive pressure ventilation directly increases serum bicarbonate"],"answer":0,"explanation":"The patient is maintaining a critically low PaCO2. Even brief apnoea or inadequate post-intubation minute ventilation can reduce pH and increase non-ionised salicylate entry into tissues. Seek toxicology advice, alkalinise and assess dialysis indications.","pearl":"Match or exceed pre-intubation minute ventilation when airway intervention is unavoidable.","reference":"EXTRIP salicylate recommendations; toxicology guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P002"},{"topic":"Practice · Cardiology","question":"A 66-year-old with regular broad-complex tachycardia at 180/min has BP 72/40, diaphoresis and altered consciousness. A prior ECG is unavailable. What is the best next step?","options":["Synchronized electrical cardioversion with appropriate sedation if feasible","Adenosine diagnostic challenge before intervention","Verapamil 5 mg IV","Amiodarone infusion over one hour before shock"],"answer":0,"explanation":"Haemodynamic instability with tachyarrhythmia warrants immediate synchronized cardioversion. Treat undifferentiated broad-complex tachycardia as ventricular until proven otherwise; AV nodal blockers may be dangerous.","pearl":"Instability determines urgency, not certainty of rhythm diagnosis.","reference":"ANZCOR tachyarrhythmia algorithm","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P003"},{"topic":"Practice · Neurology","question":"A 74-year-old on apixaban has acute intracerebral haemorrhage with neurological deterioration and a last dose 3 hours ago. CT shows 45 mL lobar bleed. Which immediate strategy is most appropriate?","options":["Initiate urgent factor Xa inhibitor reversal per local protocol and control blood pressure while engaging neurosurgery","Wait for INR before deciding on reversal","Give vitamin K as sole reversal","Administer prophylactic therapeutic heparin"],"answer":0,"explanation":"Life-threatening intracranial haemorrhage on apixaban requires prompt consideration of targeted reversal (availability and protocol dependent), blood pressure management and specialist care. INR and vitamin K do not reliably assess or reverse apixaban.","pearl":"Do not use a normal INR to exclude clinically important apixaban effect.","reference":"AHA/ASA spontaneous ICH guideline; local DOAC reversal protocol","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P004"},{"topic":"Practice · Respiratory","question":"An intubated asthmatic becomes hypotensive with high peak airway pressure, relatively normal plateau pressure and severe expiratory flow limitation. Breath sounds are bilateral. What immediate ventilator adjustment is most appropriate?","options":["Reduce minute ventilation and lengthen expiratory time","Increase respiratory rate to correct PaCO2","Increase tidal volume to 10 mL/kg","Add inspiratory pause to increase mean airway pressure"],"answer":0,"explanation":"Dynamic hyperinflation and auto-PEEP reduce venous return. Lower respiratory rate, lower tidal volume where appropriate and longer expiration limit breath stacking; permissive hypercapnia may be necessary. Evaluate other causes of shock simultaneously.","pearl":"In severe asthma, treat hyperinflation rather than normalising PaCO2.","reference":"Critical care mechanical ventilation guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P005"},{"topic":"Practice · Trauma","question":"After blunt trauma, a hypotensive patient has pelvic instability, negative FAST and no major external bleeding. A pelvic binder has been applied correctly. What is the next best haemorrhage-control pathway?","options":["Activate massive transfusion and arrange urgent pelvic haemorrhage control according to local capability","Remove binder for repeat pelvic examination","Immediate contrast CT despite persistent profound instability","Give 3 L crystalloid before blood products"],"answer":0,"explanation":"Pelvic retroperitoneal haemorrhage may not be detected by FAST. Damage-control resuscitation and definitive pelvic haemorrhage control (preperitoneal packing, angiography or operative strategy as appropriate) are priorities.","pearl":"A negative FAST does not exclude major pelvic bleeding.","reference":"ATLS principles; pelvic trauma guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P006"},{"topic":"Practice · Paediatrics","question":"A 3-year-old with severe DKA is becoming bradycardic, hypertensive and less responsive during treatment. What is the most appropriate immediate action?","options":["Administer hyperosmolar therapy for suspected cerebral injury and urgently involve intensive care","Obtain CT before treatment","Give sodium bicarbonate for all DKA patients","Increase insulin infusion to 0.2 units/kg/hour"],"answer":0,"explanation":"Clinical deterioration with signs of raised intracranial pressure in paediatric DKA warrants immediate treatment of suspected cerebral injury; imaging must not delay therapy. Review fluids and biochemical course and obtain senior support.","pearl":"Treat suspected DKA-related cerebral injury clinically.","reference":"ISPAD DKA consensus guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P007"},{"topic":"Practice · Obstetrics","question":"A woman at 33 weeks gestation has BP 188/118, headache, clonus and epigastric pain. Platelets are 78 x 10^9/L. Which initial bundle is most appropriate?","options":["Magnesium sulfate, prompt blood pressure control and urgent obstetric assessment for delivery planning","Discharge after oral antihypertensive","High-dose aspirin and review in 24 hours","Immediate large-volume crystalloid loading"],"answer":0,"explanation":"Severe pre-eclampsia with features of end-organ dysfunction requires seizure prophylaxis, urgent control of severe hypertension and coordinated obstetric management. Protein quantification should not delay care.","pearl":"HELLP features and severe symptoms mandate escalation irrespective of proteinuria.","reference":"SOMANZ hypertensive disorders of pregnancy guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P008"},{"topic":"Practice · Infectious Diseases","question":"A patient with septic shock has fever, purpura fulminans and rapidly progressive meningococcal disease. Blood cultures have not yet been obtained and lumbar puncture would be unsafe. What is the best immediate antimicrobial decision?","options":["Administer appropriate empiric IV antibiotics immediately, taking blood cultures only if this causes no material delay","Wait for lumbar puncture to target treatment","Give oral antibiotics pending imaging","Withhold antimicrobials until procalcitonin returns"],"answer":0,"explanation":"Time-critical treatment for suspected invasive meningococcal disease must not wait for LP or other diagnostics. Cultures are desirable if obtained promptly, but resuscitation and antimicrobial therapy take precedence.","pearl":"LP is neither required nor safe before antibiotics in an unstable patient.","reference":"Therapeutic Guidelines Australia; local meningococcal guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P009"},{"topic":"Practice · Renal & Metabolic","question":"A dialysis patient has potassium 7.4 mmol/L, broad QRS complexes and profound weakness. Which intervention should be delivered first?","options":["IV calcium according to local resuscitation protocol","Nebulised salbutamol alone","Sodium polystyrene sulfonate orally","Furosemide infusion"],"answer":0,"explanation":"IV calcium stabilises myocardial membrane excitability in hyperkalaemia with ECG toxicity. Follow promptly with intracellular shifting therapies and definitive potassium removal, commonly dialysis.","pearl":"ECG toxicity makes membrane stabilisation the immediate priority.","reference":"UK Kidney Association hyperkalaemia guideline; local resuscitation protocol","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P010"},{"topic":"Practice · Cardiology","question":"A 49-year-old with inferior STEMI becomes hypotensive after sublingual nitrate. JVP is elevated, lungs are clear and right-sided leads show V4R elevation. Which management is most appropriate while activating PCI?","options":["Cautious crystalloid bolus with repeated haemodynamic assessment","Further nitrates","Immediate high-dose diuresis","IV beta-blocker"],"answer":0,"explanation":"Right ventricular infarction can cause preload-dependent hypotension. Small, reassessed fluid boluses may improve output while urgent reperfusion is arranged. Avoid drugs that reduce preload when hypotensive.","pearl":"RV infarction physiology matters more than a generic STEMI drug checklist.","reference":"ESC acute coronary syndrome guideline","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P011"},{"topic":"Practice · Neurology","question":"A 42-year-old has thunderclap headache beginning 12 hours ago. Noncontrast CT brain is normal, performed on a modern scanner and read by a radiologist. Neurological examination is normal. What is the best next step?","options":["Discuss further evaluation for SAH using LP or CTA according to shared decision-making and local pathway","Discharge because CT excludes SAH at any time","Treat as migraine without further evaluation","Perform EEG"],"answer":0,"explanation":"The high sensitivity of CT within six hours cannot simply be extrapolated to 12 hours. Residual SAH risk warrants discussion of further testing and its trade-offs; choice depends on local expertise and patient factors.","pearl":"Time from onset changes the diagnostic performance of CT.","reference":"ACEP acute headache clinical policy; local SAH pathway","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P012"},{"topic":"Practice · Toxicology","question":"A patient with tricyclic antidepressant overdose has seizures, QRS 156 ms and hypotension. What is the preferred targeted treatment?","options":["IV sodium bicarbonate boluses titrated to ECG and haemodynamics","IV physostigmine","IV flecainide","High-dose propranolol"],"answer":0,"explanation":"Sodium bicarbonate is indicated for TCA-associated sodium-channel blockade manifested by QRS widening, arrhythmia or hypotension. Support airway, seizures and circulation while monitoring pH, potassium and ECG.","pearl":"Wide QRS in TCA poisoning is a sodium-channel blockade emergency.","reference":"Clinical toxicology guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P013"},{"topic":"Practice · Resuscitation","question":"A patient in cardiac arrest after suspected massive pulmonary embolism remains in PEA despite high-quality CPR. Bedside echo suggests severe RV strain, and no alternative cause is apparent. What should be considered?","options":["Systemic thrombolysis during arrest where PE is strongly suspected, with prolonged resuscitation as appropriate","Terminate resuscitation because PEA is non-shockable","Administer verapamil","Give adenosine"],"answer":0,"explanation":"When massive PE is the likely reversible cause of arrest, fibrinolysis may be considered under resuscitation guidelines; prolonged CPR may be necessary after administration. Echocardiographic RV strain alone is not definitive and context matters.","pearl":"Consider cause-directed treatment for PE arrest without waiting for CT.","reference":"ANZCOR special circumstances; ERC cardiac arrest guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P014"},{"topic":"Practice · Trauma","question":"A 27-year-old with penetrating chest trauma has profound shock, distended neck veins and absent breath sounds on the left. There is no immediate access to imaging. What is the best action?","options":["Immediate left chest decompression followed by definitive pleural drainage","Portable chest X-ray before intervention","CT chest with contrast","Pericardiocentesis without assessing chest injury"],"answer":0,"explanation":"Suspected tension pneumothorax with obstructive shock is a clinical diagnosis requiring immediate decompression. Do not delay for imaging. Technique should follow local trauma protocol and available expertise.","pearl":"Treat life-threatening tension physiology immediately.","reference":"ATLS; trauma resuscitation guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P015"},{"topic":"Practice · Paediatrics","question":"A febrile 6-week-old infant is lethargic, mottled and has delayed capillary refill. Initial glucose is 2.1 mmol/L. What is the most appropriate first-hour approach?","options":["Immediate correction of hypoglycaemia, sepsis resuscitation, cultures if promptly obtainable and parenteral antibiotics","Oral rehydration and outpatient review","Wait for urine culture before antibiotics","Lumbar puncture before vascular access"],"answer":0,"explanation":"This infant is critically unwell with possible invasive bacterial infection and hypoglycaemia. Stabilisation and empiric antibiotics are time-critical; LP can follow once safe and should not delay treatment.","pearl":"In unstable infants, resuscitation precedes definitive diagnostic sampling.","reference":"NICE fever in under 5s; local neonatal sepsis guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P016"},{"topic":"Practice · Critical Care","question":"An intubated ARDS patient has plateau pressure 34 cm H2O on volume control ventilation, tidal volume 8 mL/kg predicted body weight and PEEP 12. What adjustment most directly reduces ventilator-induced lung injury risk?","options":["Reduce tidal volume toward 6 mL/kg predicted body weight and reassess plateau/driving pressure","Increase tidal volume to 10 mL/kg","Increase respiratory rate to 35 without changing tidal volume","Switch to 100% oxygen indefinitely"],"answer":0,"explanation":"Lung-protective ventilation uses low tidal volume based on predicted body weight and limits plateau pressure. Other adjustments depend on gas exchange, haemodynamics and recruitability.","pearl":"Use predicted, not actual, body weight for tidal volume.","reference":"ARDSNet; ATS/ESICM/SCCM ARDS guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P017"},{"topic":"Practice · Surgical Emergencies","question":"A 70-year-old with atrial fibrillation develops sudden severe abdominal pain, lactate 5.2 mmol/L and minimal tenderness. Haemodynamics are stable after initial resuscitation. What is the best investigation?","options":["Urgent CT angiography of abdomen and pelvis","Plain abdominal radiograph","Colonoscopy","Ultrasound for gallstones"],"answer":0,"explanation":"Acute mesenteric ischaemia is time-critical and may present with pain out of proportion to examination. CTA is the key initial diagnostic test, alongside urgent surgical/vascular consultation.","pearl":"A soft abdomen does not exclude early mesenteric ischaemia.","reference":"World Society of Emergency Surgery acute mesenteric ischaemia guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P018"},{"topic":"Practice · Endocrine","question":"A patient with DKA has glucose 24 mmol/L, pH 7.08, potassium 2.8 mmol/L and severe dehydration. What should occur before starting insulin?","options":["Prioritise potassium replacement and monitoring while resuscitating; defer insulin until potassium is safer","Administer insulin immediately at double dose","Give bicarbonate to normalise pH","Start an SGLT2 inhibitor"],"answer":0,"explanation":"Insulin drives potassium intracellularly and can provoke lethal dysrhythmia when potassium is severely depleted. Correct potassium first with close monitoring and protocol-based fluid management.","pearl":"In DKA, dangerous hypokalaemia changes the sequence of treatment.","reference":"International hyperglycaemic crises consensus report","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P019"},{"topic":"Practice · Obstetrics","question":"A 29-year-old at 36 weeks gestation has sudden painless vaginal bleeding and a known placenta praevia. She is tachycardic with BP 90/50. Which examination should be avoided before placental location is confirmed?","options":["Digital vaginal examination","Abdominal palpation","Speculum examination under appropriate circumstances","Bedside maternal vital signs"],"answer":0,"explanation":"Digital vaginal examination can precipitate catastrophic haemorrhage in placenta praevia. Resuscitation and urgent obstetric involvement are priorities.","pearl":"Exclude placenta praevia before digital vaginal examination in late pregnancy bleeding.","reference":"RANZCOG antepartum haemorrhage guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P020"},{"topic":"Practice · Infectious Diseases","question":"A patient with necrotising soft tissue infection has severe pain, rapidly advancing erythema, hypotension and rising lactate. Broad-spectrum antibiotics have started. What intervention is most important for survival?","options":["Urgent surgical exploration and debridement","Repeat CRP in four hours","Hyperbaric oxygen before surgery","Wait for MRI to confirm fascial involvement"],"answer":0,"explanation":"Early operative source control is essential. Imaging should not delay surgery when clinical suspicion is high; antibiotics and haemodynamic support are adjuncts.","pearl":"Necrotising infection is a surgical diagnosis and time-critical source-control problem.","reference":"IDSA skin and soft tissue infection guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P021"},{"topic":"Practice · Cardiology","question":"A patient with atrial fibrillation and known Wolff–Parkinson–White syndrome presents with an irregular, very rapid wide-complex tachycardia and hypotension. Which treatment is preferred?","options":["Immediate synchronized cardioversion","IV diltiazem","IV digoxin","IV adenosine"],"answer":0,"explanation":"Pre-excited AF can deteriorate into VF with AV nodal blockers. Instability warrants synchronized cardioversion; management of stable cases requires specialist-directed drugs that do not selectively block the AV node.","pearl":"Avoid AV nodal blockers in pre-excited AF.","reference":"ESC supraventricular tachycardia guideline; resuscitation guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P022"},{"topic":"Practice · Resuscitation","question":"Following intubation of a patient with severe metabolic acidosis from shock, end-tidal CO2 rises abruptly and arterial pH deteriorates. Oxygenation and tube position are satisfactory. Which cause is most likely?","options":["Insufficient post-intubation alveolar ventilation relative to pre-intubation compensation","Excessively low inspired oxygen","An acute increase in renal bicarbonate loss alone","Improved perfusion always causes alkalosis"],"answer":0,"explanation":"Patients with severe metabolic acidosis may sustain extreme compensatory minute ventilation. Conventional ventilator settings may abruptly raise PaCO2, compounding acidaemia and haemodynamic compromise.","pearl":"Plan ventilator minute ventilation before induction in profound metabolic acidosis.","reference":"Critical care acid–base physiology guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P023"},{"topic":"Practice · Neurology","question":"A patient with acute cervical spinal cord injury is hypotensive and bradycardic, but also has pelvic fractures. Which statement best guides the initial diagnosis of neurogenic shock?","options":["Neurogenic shock is a diagnosis of exclusion after actively evaluating haemorrhagic and other causes","Bradycardia proves there is no haemorrhage","All spinal cord injuries require 3 L crystalloid","Normal FAST excludes retroperitoneal bleeding"],"answer":0,"explanation":"Neurogenic shock may produce vasodilation and bradycardia, but trauma patients can have concurrent haemorrhage. Exclude and treat bleeding while supporting spinal cord perfusion according to specialist guidance.","pearl":"Do not attribute hypotension to neurogenic shock before excluding bleeding.","reference":"Trauma and acute spinal cord injury guidelines","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P024"},{"topic":"Practice · Toxicology","question":"A patient taking metformin develops profound lactic acidosis (pH 6.91, lactate 19 mmol/L), shock and acute kidney injury. Despite resuscitation, acidaemia persists. Which treatment is most appropriate to arrange urgently?","options":["Extracorporeal treatment, usually haemodialysis, after toxicology/nephrology consultation","Activated charcoal 24 hours after ingestion","Urinary acidification","Flumazenil"],"answer":0,"explanation":"Severe metformin-associated lactic acidosis with profound acidaemia, high lactate, shock or renal failure is an indication to consider extracorporeal treatment under EXTRIP criteria.","pearl":"Use severity and organ dysfunction to guide dialysis decisions in metformin toxicity.","reference":"EXTRIP metformin recommendations","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P025"},{"topic":"Practice · Paediatrics","question":"A 4-year-old has suspected bacterial tracheitis with stridor, high fever, toxic appearance and minimal response to nebulised adrenaline. What is the safest next step?","options":["Early senior airway and anaesthetic/ENT involvement with controlled airway planning and IV antibiotics","Repeated throat examination with a tongue depressor","Discharge after oral dexamethasone","Blind nasotracheal intubation"],"answer":0,"explanation":"Bacterial tracheitis can cause rapidly progressive upper-airway obstruction and may respond poorly to croup therapy. Avoid provoking obstruction and secure expert airway support early.","pearl":"Toxic stridor unresponsive to croup therapy requires reconsideration of diagnosis.","reference":"Paediatric airway and bacterial tracheitis guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P026"},{"topic":"Practice · Critical Care","question":"An ARDS patient on low tidal volume ventilation has persistent PaO2/FiO2 of 85 despite optimisation of PEEP and FiO2. No contraindication exists. Which adjunct has the strongest established outcome benefit in severe ARDS?","options":["Prolonged prone positioning","Routine inhaled nitric oxide indefinitely","Routine high-frequency oscillatory ventilation","Routine recruitment manoeuvres at extreme pressures"],"answer":0,"explanation":"Prolonged prone positioning improves outcomes in selected severe ARDS when combined with lung-protective ventilation. Other rescue modalities may improve oxygenation without established mortality benefit or may cause harm.","pearl":"Prone early in persistent severe ARDS after optimisation.","reference":"PROSEVA trial; ARDS guideline","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P027"},{"topic":"Practice · Trauma","question":"A hypotensive trauma patient with an unstable pelvis has a correctly positioned binder. FAST is negative, but blood transfusion requirements are escalating. Which conclusion is best supported?","options":["Pelvic retroperitoneal bleeding remains a major potential source requiring definitive control","Intra-abdominal haemorrhage is excluded","Pelvic binder rules out ongoing haemorrhage","Repeat FAST every hour is definitive treatment"],"answer":0,"explanation":"FAST is insensitive to retroperitoneal bleeding. A binder is temporising; ongoing shock requires damage-control resuscitation and definitive haemorrhage control.","pearl":"A negative FAST should not reassure in pelvic trauma with shock.","reference":"Pelvic trauma consensus guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P028"},{"topic":"Practice · Renal & Metabolic","question":"A patient with severe symptomatic hyponatraemia (Na 111 mmol/L) has a generalised seizure. What is the immediate treatment priority?","options":["Controlled bolus of hypertonic saline with frequent sodium reassessment","Fluid restriction alone","Rapid correction to 140 mmol/L in six hours","Desmopressin alone without sodium therapy"],"answer":0,"explanation":"Seizures due to severe hyponatraemia warrant prompt hypertonic saline to achieve a modest early rise in sodium, with close monitoring to prevent overcorrection and osmotic demyelination.","pearl":"Treat neurological emergencies while limiting total sodium correction.","reference":"European and US hyponatraemia guidance","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P029"},{"topic":"Practice · Surgical Emergencies","question":"A 60-year-old with severe epigastric pain, fever, jaundice, hypotension and confusion has a dilated common bile duct. Antibiotics and resuscitation are underway. What is the most important next intervention?","options":["Urgent biliary decompression, usually ERCP, with specialist input","Elective outpatient MRCP","Delay intervention until bilirubin normalises","Laparoscopic cholecystectomy without considering duct drainage"],"answer":0,"explanation":"Severe acute cholangitis with organ dysfunction requires urgent source control by biliary drainage, commonly ERCP, alongside antibiotics and resuscitation.","pearl":"Source control is critical in septic obstructive cholangitis.","reference":"Tokyo Guidelines for acute cholangitis","level":"FACEM Fellowship","review_status":"Requires clinician and source verification","source":"Original FACEM-style practice","id":"P030"},{"topic":"Practice · Resuscitation","question":"During a busy ED shift, you are asked to review the following case. An inferior STEMI patient has BP 76/42, raised JVP, clear lungs and ST elevation in V4R. Best immediate supportive intervention while arranging reperfusion. Select the single best answer.","options":["Cautious 250 mL crystalloid bolus with reassessment","IV furosemide","IV metoprolol","IV GTN"],"answer":0,"explanation":"RV infarction causes preload-dependent output. Small fluid boluses may help if no congestion; urgent reperfusion remains essential.","pearl":"Avoid preload-reducing drugs in hypotensive RV infarction.","reference":"ESC ACS guideline","source":"Original FACEM-style practice","id":"P031"},{"topic":"Practice · Resuscitation","question":"At the resuscitation bay handover, the team describes this presentation: Septic shock persists at MAP 53 despite appropriate initial fluids. Preferred first-line vasopressor. Select the single best answer.","options":["Phenylephrine","Dobutamine alone","Dopamine","Noradrenaline"],"answer":3,"explanation":"Noradrenaline is preferred, initially targeting MAP approximately 65 mmHg, individualised to perfusion.","pearl":"Do not delay vasopressors in persistent shock.","reference":"Surviving Sepsis Campaign","source":"Original FACEM-style practice","id":"P032"},{"topic":"Practice · Resuscitation","question":"You are the senior emergency physician reviewing a patient. VF persists after three defibrillation attempts in adult cardiac arrest. Which antiarrhythmic is recommended. Select the single best answer.","options":["Atropine 1 mg IV","Amiodarone 300 mg IV/IO","Verapamil 5 mg IV","Metoprolol 5 mg IV"],"answer":1,"explanation":"Amiodarone 300 mg IV/IO is given after the third shock in standard shockable ALS algorithms. Continue CPR and address reversible causes.","pearl":"Know shockable arrest drug timing.","reference":"ANZCOR ALS","source":"Original FACEM-style practice","id":"P033"},{"topic":"Practice · Resuscitation","question":"A registrar requests your advice about the following presentation. A 35-year-old develops hypotension, bronchospasm and urticaria immediately after IV antibiotics. First-line drug. Select the single best answer.","options":["IM adrenaline 0.5 mg of 1 mg/mL","IV antihistamine","Nebulised salbutamol alone","IV hydrocortisone"],"answer":0,"explanation":"IM adrenaline into the lateral thigh is first-line for adult anaphylaxis; repeat if required and support airway and circulation.","pearl":"Antihistamines and steroids must not delay adrenaline.","reference":"ASCIA anaphylaxis guidance","source":"Original FACEM-style practice","id":"P034","image":"practice-capno-obstruction.png","image_note":"Illustrative teaching schematic; not an authentic patient image."},{"topic":"Practice · Resuscitation","question":"At an ED clinical decision point, consider this scenario: Regular broad-complex tachycardia at 190/min causes BP 65/35 and confusion. Pulse present. Immediate treatment. Select the single best answer.","options":["Synchronized electrical cardioversion","Oral beta blocker","IV verapamil","IV adenosine and observe"],"answer":0,"explanation":"Unstable tachyarrhythmia with a pulse requires immediate synchronized cardioversion, with sedation if feasible without delay.","pearl":"Physiology determines urgency.","reference":"ANZCOR peri-arrest guidance","source":"Original FACEM-style practice","id":"P035"},{"topic":"Practice · Cardiology","question":"You are supervising an acute assessment. Known WPW with irregular broad-complex tachycardia at 220/min. Which drug should be avoided. Select the single best answer.","options":["Expert-guided rhythm control","Procainamide","Verapamil","Ibutilide"],"answer":2,"explanation":"AV nodal blockers may accelerate conduction through an accessory pathway in pre-excited AF and precipitate VF.","pearl":"Avoid AV nodal blockers in pre-excited AF.","reference":"ACC/AHA AF guideline","source":"Original FACEM-style practice","id":"P036"},{"topic":"Practice · Cardiology","question":"An ED team is planning the next step for this presentation. Acute pulmonary oedema with BP 220/115 and severe respiratory distress. Best initial combination. Select the single best answer.","options":["NIV and titrated nitrates","IV beta blocker alone","Thrombolysis","2 L crystalloid rapidly"],"answer":0,"explanation":"NIV improves oxygenation and work of breathing; nitrates reduce preload and afterload in hypertensive pulmonary oedema.","pearl":"Address afterload and oxygenation simultaneously.","reference":"ESC heart failure guidance","source":"Original FACEM-style practice","id":"P037"},{"topic":"Practice · Cardiology","question":"During an overnight shift, you are consulted about this case. Inferior STEMI with hypotension. Which ECG finding supports RV infarction. Select the single best answer.","options":["QT prolongation","T inversion aVL alone","ST depression V1","ST elevation V4R"],"answer":3,"explanation":"Right-sided V4R ST elevation supports RV involvement, explaining preload-sensitive hypotension.","pearl":"Obtain right-sided leads in hypotensive inferior STEMI.","reference":"ESC ACS guideline","source":"Original FACEM-style practice","id":"P038"},{"topic":"Practice · Cardiology","question":"During a busy ED shift, you are asked to review the following case. A stable patient has sustained monomorphic VT at 160/min. Best management principle. Select the single best answer.","options":["Discharge after normal troponin","Treat as sinus tachycardia","Monitored antiarrhythmic or planned cardioversion with expert support","Routine IV verapamil"],"answer":2,"explanation":"Stable VT requires monitoring and active treatment with readiness for cardioversion. Drug choice depends on underlying cardiac function.","pearl":"Stable VT is not benign.","reference":"ESC ventricular arrhythmia guidance","source":"Original FACEM-style practice","id":"P039"},{"topic":"Practice · Cardiology","question":"At the resuscitation bay handover, the team describes this presentation: Mechanical mitral valve, S. aureus bacteraemia and new murmur. Which investigation is particularly important. Select the single best answer.","options":["Transoesophageal echocardiography","Coronary calcium score","Holter monitor","Exercise test"],"answer":0,"explanation":"TOE improves detection of prosthetic valve vegetations, abscesses and complications.","pearl":"Prosthetic valve endocarditis warrants TOE.","reference":"ESC endocarditis guideline","source":"Original FACEM-style practice","id":"P040"},{"topic":"Practice · Toxicology","question":"You are the senior emergency physician reviewing a patient. Massive modified-release paracetamol ingestion 8 hours earlier with concentration above treatment line. Best approach. Select the single best answer.","options":["IV acetylcysteine with serial levels and liver tests","Stop once asymptomatic","Wait until 24 hours","Charcoal only"],"answer":0,"explanation":"Delayed absorption requires acetylcysteine when indicated and serial biochemical monitoring.","pearl":"A single nomogram point is insufficient for modified-release overdose follow-up.","reference":"Australia/NZ paracetamol poisoning guidance","source":"Original FACEM-style practice","id":"P041"},{"topic":"Practice · Toxicology","question":"A registrar requests your advice about the following presentation. TCA overdose with QRS 160 ms, hypotension and ventricular ectopy. First-line targeted treatment. Select the single best answer.","options":["Phenytoin","IV sodium bicarbonate","Flumazenil","Calcium gluconate alone"],"answer":1,"explanation":"Bicarbonate counteracts sodium-channel blockade; repeat guided by ECG, haemodynamics, pH and electrolytes.","pearl":"QRS widening signals serious TCA toxicity.","reference":"Clinical toxicology guidance","source":"Original FACEM-style practice","id":"P042"},{"topic":"Practice · Toxicology","question":"At an ED clinical decision point, consider this scenario: Salicylate toxicity with tinnitus and mixed respiratory alkalosis/metabolic acidosis. Which intervention increases renal elimination. Select the single best answer.","options":["Urinary acidification","Flumazenil","High-dose furosemide","IV sodium bicarbonate for urinary alkalinisation"],"answer":3,"explanation":"Urinary alkalinisation enhances salicylate excretion, while severe toxicity may require dialysis.","pearl":"Prevent acidaemia and correct hypokalaemia.","reference":"EXTRIP salicylate guidance","source":"Original FACEM-style practice","id":"P043"},{"topic":"Practice · Toxicology","question":"You are supervising an acute assessment. Coma, pinpoint pupils and respiratory rate 5/min after suspected opioid ingestion. Immediate priority. Select the single best answer.","options":["Activated charcoal immediately","Flumazenil","CT brain first","Airway and ventilation with titrated naloxone"],"answer":3,"explanation":"Ventilate and oxygenate first; titrate naloxone to restore adequate respiratory effort and monitor for recurrence.","pearl":"Aim for adequate breathing, not necessarily full wakefulness.","reference":"Opioid poisoning management guidance","source":"Original FACEM-style practice","id":"P044"},{"topic":"Practice · Toxicology","question":"An ED team is planning the next step for this presentation. Severe methanol toxicity with visual symptoms and anion-gap acidosis. Which drug prevents toxic metabolite production. Select the single best answer.","options":["Pralidoxime","N-acetylcysteine","Fomepizole","Atropine"],"answer":2,"explanation":"Fomepizole blocks alcohol dehydrogenase and formation of formate. Severe cases may require haemodialysis.","pearl":"Treat suspected toxic alcohol poisoning before confirmatory levels if necessary.","reference":"EXTRIP methanol guidance","source":"Original FACEM-style practice","id":"P045"},{"topic":"Practice · Paediatrics","question":"During an overnight shift, you are consulted about this case. Three-year-old with life-threatening asthma has minimal air entry despite inhaled therapy and steroids. Appropriate adjunct. Select the single best answer.","options":["Oral montelukast","Routine IV antibiotics","IV furosemide","IV magnesium sulfate"],"answer":3,"explanation":"IV magnesium may help refractory severe asthma; continue bronchodilators and obtain senior critical care support.","pearl":"A silent chest is a critical warning sign.","reference":"Paediatric acute asthma guidance","source":"Original FACEM-style practice","id":"P046"},{"topic":"Practice · Paediatrics","question":"During a busy ED shift, you are asked to review the following case. Two-year-old with fever has a 4-minute generalised seizure and returns rapidly to baseline without focal findings. Best classification. Select the single best answer.","options":["Requires chronic antiepileptic therapy","Mandatory LP","Requires CT for all cases","Simple febrile seizure"],"answer":3,"explanation":"Brief generalised seizure with full recovery and no recurrence within 24 hours fits a simple febrile seizure.","pearl":"Investigations follow clinical findings, not seizure alone.","reference":"RCH febrile seizure guidance","source":"Original FACEM-style practice","id":"P047"},{"topic":"Practice · Paediatrics","question":"At the resuscitation bay handover, the team describes this presentation: Six-month-old with bronchiolitis, moderate work of breathing and SpO2 88% on room air. Initial management. Select the single best answer.","options":["Routine antibiotics","Routine salbutamol","Oxygen and supportive care","Routine corticosteroids"],"answer":2,"explanation":"Supportive care includes oxygen when indicated, hydration and airway suction as needed.","pearl":"Routine bronchodilators and steroids are not beneficial.","reference":"Australasian bronchiolitis guideline","source":"Original FACEM-style practice","id":"P048"},{"topic":"Practice · Paediatrics","question":"You are the senior emergency physician reviewing a patient. Four-year-old with suspected epiglottitis is drooling, stridulous and tripod-positioned. Safest approach. Select the single best answer.","options":["Keep calm and arrange expert-controlled airway","Unmonitored CT neck","Use tongue depressor","Force throat examination"],"answer":0,"explanation":"Avoid agitation or provocative examinations; obtain expert anaesthetic, ENT and paediatric support.","pearl":"Minimise distress in threatened upper airway obstruction.","reference":"Paediatric airway guidance","source":"Original FACEM-style practice","id":"P049"},{"topic":"Practice · Paediatrics","question":"A registrar requests your advice about the following presentation. Seven-year-old with DKA develops headache, bradycardia and falling GCS during treatment. Presume which complication. Select the single best answer.","options":["Migraine","Benign drug effect","Hypocalcaemia","Cerebral injury/oedema"],"answer":3,"explanation":"Neurological deterioration suggests cerebral injury; administer protocol-based hyperosmolar therapy without delaying for CT.","pearl":"Treat suspected DKA cerebral injury clinically.","reference":"ISPAD DKA guideline","source":"Original FACEM-style practice","id":"P050"},{"topic":"Practice · Trauma","question":"At an ED clinical decision point, consider this scenario: Blunt trauma with profound hypotension, respiratory distress and unilateral absent breath sounds. Immediate priority. Select the single best answer.","options":["IV furosemide","Chest X-ray","Pleural decompression","CT chest"],"answer":2,"explanation":"Suspected tension pneumothorax in an unstable patient requires immediate decompression without imaging delay.","pearl":"Tension pneumothorax is a clinical diagnosis.","reference":"Trauma resuscitation guidance","source":"Original FACEM-style practice","id":"P051"},{"topic":"Practice · Trauma","question":"You are supervising an acute assessment. Unstable blunt trauma patient has positive FAST. Next priority. Select the single best answer.","options":["Urgent surgical haemorrhage control and resuscitation","Discharge","Colonoscopy","CT abdomen first"],"answer":0,"explanation":"Shock with intraperitoneal free fluid strongly suggests bleeding requiring operative control.","pearl":"Do not transport unstable patients to CT unnecessarily.","reference":"ATLS principles","source":"Original FACEM-style practice","id":"P052"},{"topic":"Practice · Trauma","question":"An ED team is planning the next step for this presentation. Hypotensive patient with suspected unstable pelvic fracture needs binder placement. Correct level. Select the single best answer.","options":["Lower ribs","Umbilicus","Iliac crests","Greater trochanters"],"answer":3,"explanation":"Pelvic binders should be placed over the greater trochanters for effective mechanical reduction.","pearl":"A binder positioned too high may be ineffective.","reference":"Pelvic trauma guidance","source":"Original FACEM-style practice","id":"P053"},{"topic":"Practice · Trauma","question":"During an overnight shift, you are consulted about this case. Penetrating chest trauma with shock, elevated JVP and pericardial fluid on eFAST. Priority. Select the single best answer.","options":["Beta blockade","Urgent operative management of tamponade","IV furosemide","Outpatient echo"],"answer":1,"explanation":"Traumatic tamponade needs immediate surgical management; pericardiocentesis may only temporise selected cases.","pearl":"Penetrating traumatic tamponade is a surgical emergency.","reference":"ATLS principles","source":"Original FACEM-style practice","id":"P054"},{"topic":"Practice · Trauma","question":"During a busy ED shift, you are asked to review the following case. Trauma patient with suspected C-spine injury needs intubation for airway protection. Best principle. Select the single best answer.","options":["Manual in-line stabilisation while securing airway","Force neck extension","Avoid preoxygenation","Wait for imaging"],"answer":0,"explanation":"Prioritise oxygenation and airway management with experienced operator and spinal motion restriction.","pearl":"Spinal precautions must not compromise airway care.","reference":"Trauma airway guidance","source":"Original FACEM-style practice","id":"P055"},{"topic":"Practice · Neurology","question":"At the resuscitation bay handover, the team describes this presentation: Thunderclap headache 14 hours earlier; normal noncontrast CT brain. Next step. Select the single best answer.","options":["Discharge without advice","Outpatient EEG","CT definitively excludes SAH","Further investigation using LP or appropriate vascular imaging"],"answer":3,"explanation":"CT sensitivity decreases with time; further testing is appropriate when suspicion for SAH remains.","pearl":"The six-hour CT rule does not apply at 14 hours.","reference":"AHA/ASA SAH guideline","source":"Original FACEM-style practice","id":"P056"},{"topic":"Practice · Neurology","question":"You are the senior emergency physician reviewing a patient. Disabling ischaemic stroke with large vessel occlusion and favourable imaging at 10 hours. What should be considered. Select the single best answer.","options":["Immediate carotid endarterectomy","No reperfusion after 6 hours","Endovascular thrombectomy if eligible","Routine heparin"],"answer":2,"explanation":"Selected patients benefit from thrombectomy beyond 6 hours according to tissue and vascular imaging.","pearl":"Time alone does not exclude thrombectomy.","reference":"AHA/ASA stroke guidance","source":"Original FACEM-style practice","id":"P057"},{"topic":"Practice · Neurology","question":"A registrar requests your advice about the following presentation. Generalised convulsions ongoing for 7 minutes with IV access. Preferred first-line medication class. Select the single best answer.","options":["Phenytoin","Levetiracetam alone","Propofol without airway planning","Benzodiazepine"],"answer":3,"explanation":"Treat convulsive status promptly with adequate-dose benzodiazepine and assess reversible causes.","pearl":"Five minutes of convulsions warrants status treatment.","reference":"Status epilepticus guidance","source":"Original FACEM-style practice","id":"P058"},{"topic":"Practice · Neurology","question":"At an ED clinical decision point, consider this scenario: Acute vertigo with profound truncal ataxia and inability to walk. Important diagnosis to exclude. Select the single best answer.","options":["Otitis externa","Vestibular migraine only","BPPV","Posterior circulation stroke"],"answer":3,"explanation":"Cerebellar stroke can present with severe gait instability; early CT is insensitive for posterior fossa infarction.","pearl":"Normal CT does not rule out posterior circulation stroke.","reference":"GRACE-3 dizziness guideline","source":"Original FACEM-style practice","id":"P059"},{"topic":"Practice · Neurology","question":"You are supervising an acute assessment. Warfarin-associated intracerebral haemorrhage with INR 3.8. Urgent reversal. Select the single best answer.","options":["Protamine","Oral vitamin K alone","Four-factor PCC and IV vitamin K","Delayed FFP alone"],"answer":2,"explanation":"Four-factor PCC rapidly replaces clotting factors; IV vitamin K sustains reversal.","pearl":"Reverse anticoagulation promptly in ICH.","reference":"AHA/ASA ICH guideline","source":"Original FACEM-style practice","id":"P060"},{"topic":"Practice · Infectious Diseases","question":"An ED team is planning the next step for this presentation. Suspected bacterial meningitis; LP delayed for CT. Priority. Select the single best answer.","options":["Blood cultures then immediate empiric IV antibiotics without delay","Oral antibiotics","Observe","Wait for LP"],"answer":0,"explanation":"Do not delay antibiotics for neuroimaging or LP; give dexamethasone when indicated.","pearl":"Time to antibiotics matters.","reference":"Bacterial meningitis guidance","source":"Original FACEM-style practice","id":"P061"},{"topic":"Practice · Infectious Diseases","question":"During an overnight shift, you are consulted about this case. Rapidly progressive leg pain, fever, hypotension and skin discolouration with pain out of proportion. Key intervention. Select the single best answer.","options":["Oral antibiotics and discharge","Topical antiseptic","Urgent surgical debridement","Wait for MRI"],"answer":2,"explanation":"Necrotising infection needs immediate surgical source control with broad-spectrum antibiotics and resuscitation.","pearl":"Imaging must not delay surgery.","reference":"IDSA soft tissue infection guidance","source":"Original FACEM-style practice","id":"P062"},{"topic":"Practice · Infectious Diseases","question":"During a busy ED shift, you are asked to review the following case. Chemotherapy patient with fever 39°C, ANC 0.2 and shock. Priority. Select the single best answer.","options":["Wait for neutrophil recovery","Wait for cultures","Prompt antipseudomonal IV antibiotics and sepsis resuscitation","Oral amoxicillin alone"],"answer":2,"explanation":"Neutropenic septic shock is time-critical; obtain cultures without delaying broad-spectrum treatment.","pearl":"Treat high-risk neutropenic fever immediately.","reference":"Febrile neutropenia guidance","source":"Original FACEM-style practice","id":"P063"},{"topic":"Practice · Infectious Diseases","question":"At the resuscitation bay handover, the team describes this presentation: Haemodynamically stable suspected endocarditis. Preferred microbiology before antibiotics. Select the single best answer.","options":["Multiple blood culture sets from separate venepunctures","Urine culture alone","No cultures","Throat swab"],"answer":0,"explanation":"Multiple blood cultures improve organism identification; do not delay therapy if unstable.","pearl":"Culture before antibiotics when clinically safe.","reference":"ESC endocarditis guideline","source":"Original FACEM-style practice","id":"P064"},{"topic":"Practice · Infectious Diseases","question":"You are the senior emergency physician reviewing a patient. Shock with obstructed infected ureteric stone on CT. Essential intervention beyond antibiotics. Select the single best answer.","options":["Steroids","Wait for spontaneous passage","Urgent urinary decompression","Outpatient lithotripsy"],"answer":2,"explanation":"An infected obstructed collecting system requires urgent stent or nephrostomy for source control.","pearl":"Antibiotics alone cannot resolve obstructed sepsis.","reference":"EAU urolithiasis guidance","source":"Original FACEM-style practice","id":"P065"},{"topic":"Practice · Obstetrics & Gynaecology","question":"A registrar requests your advice about the following presentation. 34-week pregnancy with severe hypertension and eclamptic seizure. Preferred drug to prevent recurrence. Select the single best answer.","options":["Diazepam maintenance","Phenytoin","Magnesium sulfate","Valproate"],"answer":2,"explanation":"Magnesium sulfate is first-line; stabilise airway, treat severe hypertension and involve obstetrics.","pearl":"Magnesium is preferred for eclampsia.","reference":"NICE pregnancy hypertension guidance","source":"Original FACEM-style practice","id":"P066"},{"topic":"Practice · Obstetrics & Gynaecology","question":"At an ED clinical decision point, consider this scenario: Positive pregnancy test, syncope, severe abdominal pain, BP 75/40 and free pelvic fluid. Priority. Select the single best answer.","options":["Urgent surgery for presumed ruptured ectopic pregnancy","Outpatient methotrexate","Discharge","Serial beta-hCG"],"answer":0,"explanation":"Resuscitate and arrange urgent gynaecological operative management for suspected haemorrhagic ectopic pregnancy.","pearl":"Do not delay definitive control in shock.","reference":"RCOG ectopic pregnancy guidance","source":"Original FACEM-style practice","id":"P067"},{"topic":"Practice · Obstetrics & Gynaecology","question":"You are supervising an acute assessment. Major postpartum haemorrhage from uterine atony. First-line uterotonic. Select the single best answer.","options":["Magnesium sulfate","Terbutaline","Oxytocin","Methotrexate"],"answer":2,"explanation":"Oxytocin is first-line alongside uterine massage, resuscitation, tranexamic acid when indicated and escalation.","pearl":"Resuscitation and haemorrhage control occur together.","reference":"WHO postpartum haemorrhage guidance","source":"Original FACEM-style practice","id":"P068"},{"topic":"Practice · Obstetrics & Gynaecology","question":"An ED team is planning the next step for this presentation. Sudden unilateral pelvic pain, enlarged ovary, but preserved Doppler flow. Best interpretation. Select the single best answer.","options":["Discharge","Flow excludes torsion","Torsion remains possible; urgent gynaecology assessment","Proves PID"],"answer":2,"explanation":"Dual ovarian blood supply and intermittent torsion mean Doppler flow cannot exclude torsion.","pearl":"Normal Doppler does not rule out torsion.","reference":"ACOG adnexal torsion guidance","source":"Original FACEM-style practice","id":"P069"},{"topic":"Practice · Obstetrics & Gynaecology","question":"During an overnight shift, you are consulted about this case. At 30 weeks gestation, painless vaginal bleeding with soft non-tender uterus. What should be avoided until placenta praevia is excluded. Select the single best answer.","options":["Ultrasound","Digital vaginal examination","Fetal monitoring","Maternal resuscitation"],"answer":1,"explanation":"Digital vaginal examination may trigger severe haemorrhage in placenta praevia.","pearl":"Establish placental location first.","reference":"RCOG placenta praevia guidance","source":"Original FACEM-style practice","id":"P070"},{"topic":"Practice · Resuscitation","question":"During a busy ED shift, you are asked to review the following case. A ventilated trauma patient becomes profoundly hypotensive with unilateral absent breath sounds. Immediate action. Select the single best answer.","options":["CT chest","Needle or finger thoracostomy","Increase PEEP","IV furosemide"],"answer":1,"explanation":"Treat tension pneumothorax immediately; do not delay decompression for imaging.","pearl":"Treat tension pneumothorax immediately; do not delay decompression for imaging.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P071"},{"topic":"Practice · Resuscitation","question":"At the resuscitation bay handover, the team describes this presentation: A patient with K 7.6 mmol/L has a sine-wave ECG. First medication. Select the single best answer.","options":["IV furosemide","Sodium polystyrene","Nebulised salbutamol","IV calcium"],"answer":3,"explanation":"IV calcium immediately stabilises the myocardium; potassium-shifting and removal therapies follow.","pearl":"IV calcium immediately stabilises the myocardium; potassium-shifting and removal therapies follow.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P072"},{"topic":"Practice · Resuscitation","question":"You are the senior emergency physician reviewing a patient. After ROSC, a comatose patient has SpO2 100% on FiO2 1.0. Best oxygen strategy. Select the single best answer.","options":["Stop oxygen immediately","Target SpO2 85%","Maintain FiO2 1.0 indefinitely","Titrate oxygen to avoid hypoxaemia and hyperoxaemia"],"answer":3,"explanation":"Titrate oxygen using reliable saturation or blood gas measurement to avoid both extremes.","pearl":"Titrate oxygen using reliable saturation or blood gas measurement to avoid both extremes.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P073"},{"topic":"Practice · Resuscitation","question":"A registrar requests your advice about the following presentation. A 70 kg adult has refractory anaphylactic shock despite repeated IM adrenaline. Next escalation. Select the single best answer.","options":["Titrated IV adrenaline infusion with expert monitoring","Oral prednisolone","IV beta blocker","IV antihistamine alone"],"answer":0,"explanation":"Refractory anaphylaxis warrants monitored IV adrenaline infusion and aggressive resuscitation.","pearl":"Refractory anaphylaxis warrants monitored IV adrenaline infusion and aggressive resuscitation.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P074"},{"topic":"Practice · Resuscitation","question":"At an ED clinical decision point, consider this scenario: A septic patient has MAP 55 despite initial fluids and signs of overload. First vasopressor. Select the single best answer.","options":["Dopamine","Milrinone","Isoprenaline","Noradrenaline"],"answer":3,"explanation":"Noradrenaline is first-line for septic shock; avoid indiscriminate further fluids.","pearl":"Noradrenaline is first-line for septic shock; avoid indiscriminate further fluids.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P075"},{"topic":"Practice · Resuscitation","question":"You are supervising an acute assessment. A 30-year-old has severe asthma, rising PaCO2 and drowsiness. What does rising CO2 imply. Select the single best answer.","options":["Expected recovery","No significance","Anxiety-related hyperventilation","Impending ventilatory failure"],"answer":3,"explanation":"Normalising or rising PaCO2 in severe asthma can signal exhaustion and impending respiratory failure.","pearl":"Normalising or rising PaCO2 in severe asthma can signal exhaustion and impending respiratory failure.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P076"},{"topic":"Practice · Resuscitation","question":"An ED team is planning the next step for this presentation. A patient in PEA has ultrasound showing a large pericardial effusion and right-sided collapse. Targeted intervention. Select the single best answer.","options":["Adenosine","Urgent pericardial decompression","IV diuretic","Defibrillation"],"answer":1,"explanation":"Tamponade is a reversible obstructive cause of PEA; urgent drainage is required.","pearl":"Tamponade is a reversible obstructive cause of PEA; urgent drainage is required.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P077"},{"topic":"Practice · Resuscitation","question":"During an overnight shift, you are consulted about this case. A patient with shock and bradycardia remains unstable after atropine. Next action. Select the single best answer.","options":["Oral beta blocker","Adenosine","Discharge","Transcutaneous pacing or vasoactive infusion"],"answer":3,"explanation":"Persistent unstable bradycardia requires pacing and/or catecholamine support.","pearl":"Persistent unstable bradycardia requires pacing and/or catecholamine support.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P078"},{"topic":"Practice · Resuscitation","question":"During a busy ED shift, you are asked to review the following case. An unconscious diabetic has capillary glucose 1.4 mmol/L. Best immediate treatment with IV access. Select the single best answer.","options":["IV dextrose","Glucagon only after CT","Subcutaneous insulin","Oral glucose"],"answer":0,"explanation":"Severe symptomatic hypoglycaemia requires immediate parenteral glucose.","pearl":"Severe symptomatic hypoglycaemia requires immediate parenteral glucose.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P079"},{"topic":"Practice · Resuscitation","question":"At the resuscitation bay handover, the team describes this presentation: A shocked patient with severe metabolic acidosis has pH 7.04 and lactate 11. Most important initial priority. Select the single best answer.","options":["Identify and reverse the cause of shock","Delay source control","Restrict oxygen","Give bicarbonate to normalise pH in all cases"],"answer":0,"explanation":"Correction of hypoperfusion and the underlying cause is the priority; bicarbonate is selective.","pearl":"Correction of hypoperfusion and the underlying cause is the priority; bicarbonate is selective.","reference":"ANZCOR ALS guidelines; local resuscitation protocols","source":"Original FACEM-style practice","id":"P080"},{"topic":"Practice · Cardiology","question":"You are the senior emergency physician reviewing a patient. An irregular wide-complex tachycardia in a patient with WPW is haemodynamically stable. Which drug must be avoided. Select the single best answer.","options":["Ibutilide","Procainamide","Expert-guided cardioversion","Verapamil"],"answer":3,"explanation":"AV nodal blockers can accelerate accessory pathway conduction and cause VF.","pearl":"AV nodal blockers can accelerate accessory pathway conduction and cause VF.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P081"},{"topic":"Practice · Cardiology","question":"A registrar requests your advice about the following presentation. A patient with chest pain has ST depression V1–V3 and tall R waves. Which leads help diagnose posterior STEMI. Select the single best answer.","options":["aVR only","V1 only","V3R–V4R","V7–V9"],"answer":3,"explanation":"Posterior leads V7–V9 can reveal posterior ST elevation.","pearl":"Posterior leads V7–V9 can reveal posterior ST elevation.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P082","image":"practice-ecg-posterior.png","image_note":"Illustrative teaching schematic; not an authentic patient image."},{"topic":"Practice · Cardiology","question":"At an ED clinical decision point, consider this scenario: A patient with suspected acute aortic dissection is stable. Preferred diagnostic imaging. Select the single best answer.","options":["Plain chest film alone","CT angiography of aorta","Coronary calcium score","Exercise ECG"],"answer":1,"explanation":"CTA provides rapid anatomical confirmation of acute aortic syndromes.","pearl":"CTA provides rapid anatomical confirmation of acute aortic syndromes.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P083"},{"topic":"Practice · Cardiology","question":"You are supervising an acute assessment. A stable regular narrow-complex tachycardia persists after vagal manoeuvres. Next drug. Select the single best answer.","options":["Amiodarone first-line","Atropine","Adenosine","Digoxin loading"],"answer":2,"explanation":"Adenosine is appropriate for regular AV-node-dependent SVT under monitoring.","pearl":"Adenosine is appropriate for regular AV-node-dependent SVT under monitoring.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P084"},{"topic":"Practice · Cardiology","question":"An ED team is planning the next step for this presentation. A patient with acute pulmonary oedema and BP 210/120 remains distressed. Best initial strategy. Select the single best answer.","options":["Immediate oral beta blocker","Two litres crystalloid","NIV and titrated nitrates","Routine thrombolysis"],"answer":2,"explanation":"NIV and nitrates improve oxygenation and reduce afterload in hypertensive pulmonary oedema.","pearl":"NIV and nitrates improve oxygenation and reduce afterload in hypertensive pulmonary oedema.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P085"},{"topic":"Practice · Cardiology","question":"During an overnight shift, you are consulted about this case. A patient with syncope has a harsh systolic murmur radiating to carotids. Most concerning lesion. Select the single best answer.","options":["Pulmonary regurgitation","Tricuspid regurgitation","Mitral stenosis","Severe aortic stenosis"],"answer":3,"explanation":"Exertional syncope with an ejection murmur suggests haemodynamically significant aortic stenosis.","pearl":"Exertional syncope with an ejection murmur suggests haemodynamically significant aortic stenosis.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P086"},{"topic":"Practice · Cardiology","question":"During a busy ED shift, you are asked to review the following case. A patient has chest pain, diffuse ST elevation and PR depression. Most likely diagnosis. Select the single best answer.","options":["Anterior STEMI","Hyperkalaemia","Digoxin effect","Acute pericarditis"],"answer":3,"explanation":"Diffuse ST elevation and PR depression are typical of acute pericarditis.","pearl":"Diffuse ST elevation and PR depression are typical of acute pericarditis.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P087"},{"topic":"Practice · Cardiology","question":"At the resuscitation bay handover, the team describes this presentation: A patient with acute MI develops hypotension, new pansystolic murmur and pulmonary oedema. Suspect. Select the single best answer.","options":["Stable angina","Papillary muscle rupture","Pericarditis","Sinus bradycardia"],"answer":1,"explanation":"Acute severe mitral regurgitation after MI can result from papillary muscle rupture.","pearl":"Acute severe mitral regurgitation after MI can result from papillary muscle rupture.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P088"},{"topic":"Practice · Cardiology","question":"You are the senior emergency physician reviewing a patient. A patient with AF and ventricular rate 180 is shocked and confused. Immediate treatment. Select the single best answer.","options":["Routine observation","Synchronized electrical cardioversion","Oral metoprolol only","Aspirin"],"answer":1,"explanation":"Haemodynamic instability due to AF mandates urgent synchronized cardioversion.","pearl":"Haemodynamic instability due to AF mandates urgent synchronized cardioversion.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P089"},{"topic":"Practice · Cardiology","question":"A registrar requests your advice about the following presentation. A patient with tamponade has hypotension and right ventricular diastolic collapse. Definitive intervention. Select the single best answer.","options":["High-dose furosemide","Oral beta blocker","Urgent pericardial drainage","Exercise testing"],"answer":2,"explanation":"Tamponade with haemodynamic compromise requires prompt drainage.","pearl":"Tamponade with haemodynamic compromise requires prompt drainage.","reference":"ESC acute coronary syndrome and arrhythmia guidance","source":"Original FACEM-style practice","id":"P090"},{"topic":"Practice · Respiratory","question":"At an ED clinical decision point, consider this scenario: A patient with COPD exacerbation has pH 7.27 and PaCO2 74 mmHg despite medical treatment. Best ventilatory support. Select the single best answer.","options":["Non-invasive ventilation","No ventilatory support","High-flow oxygen alone indefinitely","Routine CPAP without pressure support"],"answer":0,"explanation":"NIV reduces intubation and mortality in selected acidotic COPD exacerbations.","pearl":"NIV reduces intubation and mortality in selected acidotic COPD exacerbations.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P091"},{"topic":"Practice · Respiratory","question":"You are supervising an acute assessment. A patient with acute pleuritic pain, tachycardia and hypoxaemia has high clinical probability of PE. Next imaging if stable. Select the single best answer.","options":["Spirometry","D-dimer to exclude PE","CT pulmonary angiography","Chest radiograph alone"],"answer":2,"explanation":"High-probability suspected PE generally requires definitive imaging rather than D-dimer exclusion.","pearl":"High-probability suspected PE generally requires definitive imaging rather than D-dimer exclusion.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P092"},{"topic":"Practice · Respiratory","question":"An ED team is planning the next step for this presentation. A patient with severe asthma has a silent chest and exhaustion. Interpretation. Select the single best answer.","options":["Life-threatening airflow obstruction","Clinical improvement","Mild asthma","Pure anxiety"],"answer":0,"explanation":"Silent chest and exhaustion indicate critical obstruction and impending respiratory failure.","pearl":"Silent chest and exhaustion indicate critical obstruction and impending respiratory failure.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P093"},{"topic":"Practice · Respiratory","question":"During an overnight shift, you are consulted about this case. A patient with pneumonia develops a large loculated pleural collection with pH 7.05. Management. Select the single best answer.","options":["Antibiotics and pleural drainage","Oral antibiotics alone","Observation","Routine bronchodilator"],"answer":0,"explanation":"Complicated parapneumonic effusions with low pH usually require drainage.","pearl":"Complicated parapneumonic effusions with low pH usually require drainage.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P094","image":"practice-us-pleural-effusion.png","image_note":"Illustrative teaching schematic; not an authentic patient image."},{"topic":"Practice · Respiratory","question":"During a busy ED shift, you are asked to review the following case. A patient with haemoptysis becomes hypoxic and hypotensive. Immediate priority. Select the single best answer.","options":["Airway protection and positioning to protect unaffected lung","Oral antibiotics only","CT before resuscitation","Discharge"],"answer":0,"explanation":"Massive haemoptysis kills by asphyxiation; airway management takes priority.","pearl":"Massive haemoptysis kills by asphyxiation; airway management takes priority.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P095"},{"topic":"Practice · Respiratory","question":"At the resuscitation bay handover, the team describes this presentation: A patient with sudden unilateral pleuritic pain has a small primary spontaneous pneumothorax and no breathlessness. Appropriate strategy. Select the single best answer.","options":["High-dose steroids","Routine thrombolysis","Conservative observation with follow-up when eligible","Mandatory thoracotomy"],"answer":2,"explanation":"Selected stable primary spontaneous pneumothoraces can be managed conservatively.","pearl":"Selected stable primary spontaneous pneumothoraces can be managed conservatively.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P096","image":"practice-us-lung-mmode.png","image_note":"Illustrative teaching schematic; not an authentic patient image."},{"topic":"Practice · Respiratory","question":"You are the senior emergency physician reviewing a patient. A patient has diffuse bilateral infiltrates, severe hypoxaemia and no evidence of cardiogenic oedema. Syndrome. Select the single best answer.","options":["ARDS","Pneumothorax","Isolated PE","Asthma alone"],"answer":0,"explanation":"ARDS is acute non-cardiogenic respiratory failure with bilateral opacities and hypoxaemia.","pearl":"ARDS is acute non-cardiogenic respiratory failure with bilateral opacities and hypoxaemia.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P097"},{"topic":"Practice · Respiratory","question":"A registrar requests your advice about the following presentation. An obese patient with OSA receives opioids and develops hypoventilation. Immediate priority. Select the single best answer.","options":["More opioids","Discharge","Support ventilation and reverse opioid effect if indicated","Routine diuretics"],"answer":2,"explanation":"Treat hypoventilation promptly; naloxone may be required when opioids contribute.","pearl":"Treat hypoventilation promptly; naloxone may be required when opioids contribute.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P098"},{"topic":"Practice · Respiratory","question":"At an ED clinical decision point, consider this scenario: A patient has acute stridor after extubation. Most concerning mechanism. Select the single best answer.","options":["Lower lobe pneumonia","Upper airway oedema","Pulmonary embolism","Pleural effusion"],"answer":1,"explanation":"Post-extubation stridor indicates potential upper airway narrowing requiring urgent assessment.","pearl":"Post-extubation stridor indicates potential upper airway narrowing requiring urgent assessment.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P099"},{"topic":"Practice · Respiratory","question":"You are supervising an acute assessment. A patient with severe pneumonia and shock has lactate 5.4. Which management is time critical. Select the single best answer.","options":["Wait for sputum culture","Outpatient review","Oral cough syrup","Prompt IV antibiotics and haemodynamic resuscitation"],"answer":3,"explanation":"Severe pneumonia with shock requires immediate sepsis treatment.","pearl":"Severe pneumonia with shock requires immediate sepsis treatment.","reference":"BTS respiratory guidance; GINA asthma strategy","source":"Original FACEM-style practice","id":"P100"},{"topic":"Practice · Toxicology","question":"An ED team is planning the next step for this presentation. A patient with TCA overdose has QRS 160 ms and hypotension. Targeted treatment. Select the single best answer.","options":["Phenytoin","IV sodium bicarbonate","IV calcium only","Flumazenil"],"answer":1,"explanation":"Sodium bicarbonate treats TCA-related sodium-channel blockade.","pearl":"Sodium bicarbonate treats TCA-related sodium-channel blockade.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P101"},{"topic":"Practice · Toxicology","question":"During an overnight shift, you are consulted about this case. A patient has salicylate poisoning with tinnitus, acidosis and tachypnoea. Elimination strategy. Select the single best answer.","options":["Flumazenil","Urine acidification","Urinary alkalinisation with bicarbonate","Forced diuresis alone"],"answer":2,"explanation":"Urinary alkalinisation enhances salicylate excretion; severe toxicity may require dialysis.","pearl":"Urinary alkalinisation enhances salicylate excretion; severe toxicity may require dialysis.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P102"},{"topic":"Practice · Toxicology","question":"During a busy ED shift, you are asked to review the following case. A patient with suspected opioid overdose is apnoeic with pinpoint pupils. Priority. Select the single best answer.","options":["Flumazenil","Ventilation and titrated naloxone","Activated charcoal by mouth","CT before airway support"],"answer":1,"explanation":"Ventilation is immediately lifesaving; naloxone restores respiratory drive.","pearl":"Ventilation is immediately lifesaving; naloxone restores respiratory drive.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P103"},{"topic":"Practice · Toxicology","question":"At the resuscitation bay handover, the team describes this presentation: A patient with methanol ingestion has visual symptoms and high-anion-gap acidosis. Antidote. Select the single best answer.","options":["Atropine","Fomepizole","Pralidoxime","N-acetylcysteine"],"answer":1,"explanation":"Fomepizole blocks alcohol dehydrogenase; dialysis may be needed.","pearl":"Fomepizole blocks alcohol dehydrogenase; dialysis may be needed.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P104"},{"topic":"Practice · Toxicology","question":"You are the senior emergency physician reviewing a patient. A patient with organophosphate exposure has bronchorrhoea, bradycardia and miosis. Antidote. Select the single best answer.","options":["N-acetylcysteine","Naloxone","Atropine","Glucagon"],"answer":2,"explanation":"Atropine reverses muscarinic toxicity; oximes may also be indicated.","pearl":"Atropine reverses muscarinic toxicity; oximes may also be indicated.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P105"},{"topic":"Practice · Toxicology","question":"A registrar requests your advice about the following presentation. A patient with severe calcium-channel blocker overdose remains shocked despite fluids. Adjunct. Select the single best answer.","options":["Beta blocker","Adenosine","Verapamil","High-dose insulin euglycaemic therapy"],"answer":3,"explanation":"High-dose insulin can improve myocardial function in severe CCB poisoning.","pearl":"High-dose insulin can improve myocardial function in severe CCB poisoning.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P106"},{"topic":"Practice · Toxicology","question":"At an ED clinical decision point, consider this scenario: A patient with lithium toxicity has severe ataxia, confusion and renal impairment. Enhanced elimination. Select the single best answer.","options":["Activated charcoal","Haemodialysis","Urinary acidification","Naloxone"],"answer":1,"explanation":"Severe lithium toxicity with neurological signs warrants urgent dialysis consideration.","pearl":"Severe lithium toxicity with neurological signs warrants urgent dialysis consideration.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P107"},{"topic":"Practice · Toxicology","question":"You are supervising an acute assessment. A patient develops seizures and arrhythmias after local anaesthetic injection. Specific treatment. Select the single best answer.","options":["Pralidoxime","Fomepizole","IV lipid emulsion","N-acetylcysteine"],"answer":2,"explanation":"Lipid emulsion is used for severe local anaesthetic systemic toxicity.","pearl":"Lipid emulsion is used for severe local anaesthetic systemic toxicity.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P108"},{"topic":"Practice · Toxicology","question":"An ED team is planning the next step for this presentation. A patient on serotonergic agents has clonus, hyperreflexia and hyperthermia. Diagnosis. Select the single best answer.","options":["Serotonin toxicity","Anticholinergic toxicity","Neuroleptic malignant syndrome","Opioid toxicity"],"answer":0,"explanation":"Clonus and hyperreflexia strongly suggest serotonin toxicity.","pearl":"Clonus and hyperreflexia strongly suggest serotonin toxicity.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P109"},{"topic":"Practice · Toxicology","question":"During an overnight shift, you are consulted about this case. A patient with severe iron poisoning has shock and metabolic acidosis. Chelator. Select the single best answer.","options":["Deferoxamine","Dimercaprol","Penicillamine","Fomepizole"],"answer":0,"explanation":"Deferoxamine is the specific chelator for severe iron poisoning.","pearl":"Deferoxamine is the specific chelator for severe iron poisoning.","reference":"TOXBASE / local Poisons Centre guidance","source":"Original FACEM-style practice","id":"P110"},{"topic":"Practice · Paediatrics","question":"During a busy ED shift, you are asked to review the following case. A child with croup has stridor at rest and marked recession. Treatment. Select the single best answer.","options":["Salbutamol only","Dexamethasone and nebulised adrenaline","Antihistamine only","Routine antibiotics"],"answer":1,"explanation":"Corticosteroids and nebulised adrenaline are indicated in severe croup.","pearl":"Corticosteroids and nebulised adrenaline are indicated in severe croup.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P111"},{"topic":"Practice · Paediatrics","question":"At the resuscitation bay handover, the team describes this presentation: An infant has bilious vomiting and abdominal distension. Critical diagnosis to exclude. Select the single best answer.","options":["Gastro-oesophageal reflux","Colic","Malrotation with volvulus","Pyloric stenosis"],"answer":2,"explanation":"Bilious vomiting in infancy warrants urgent surgical assessment for volvulus.","pearl":"Bilious vomiting in infancy warrants urgent surgical assessment for volvulus.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P112"},{"topic":"Practice · Paediatrics","question":"You are the senior emergency physician reviewing a patient. A toddler has intermittent severe abdominal pain and red currant jelly stool. Likely diagnosis. Select the single best answer.","options":["Gastroenteritis only","Pyloric stenosis","Meckel diverticulitis","Intussusception"],"answer":3,"explanation":"Intussusception causes episodic pain and sometimes bloody mucus stool.","pearl":"Intussusception causes episodic pain and sometimes bloody mucus stool.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P113"},{"topic":"Practice · Paediatrics","question":"A registrar requests your advice about the following presentation. A febrile child has petechiae, prolonged capillary refill and hypotension. Priority. Select the single best answer.","options":["Oral antihistamine","Immediate antibiotics and shock resuscitation","Wait for lumbar puncture","Discharge"],"answer":1,"explanation":"Suspected meningococcal sepsis requires immediate treatment.","pearl":"Suspected meningococcal sepsis requires immediate treatment.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P114"},{"topic":"Practice · Paediatrics","question":"At an ED clinical decision point, consider this scenario: A child with DKA develops headache, bradycardia and reduced GCS during treatment. Suspect. Select the single best answer.","options":["Migraine","Hypocalcaemia only","Cerebral injury","Clinical recovery"],"answer":2,"explanation":"DKA-related cerebral injury needs immediate treatment and senior escalation.","pearl":"DKA-related cerebral injury needs immediate treatment and senior escalation.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P115"},{"topic":"Practice · Paediatrics","question":"You are supervising an acute assessment. A 7-week-old has projectile non-bilious vomiting and hypochloraemic alkalosis. Diagnosis. Select the single best answer.","options":["Malrotation with volvulus","Pyloric stenosis","Hirschsprung disease","Intussusception"],"answer":1,"explanation":"Pyloric stenosis produces progressive projectile non-bilious vomiting and metabolic alkalosis.","pearl":"Pyloric stenosis produces progressive projectile non-bilious vomiting and metabolic alkalosis.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P116"},{"topic":"Practice · Paediatrics","question":"An ED team is planning the next step for this presentation. A child with fever, painful hip rotation and refusal to weight-bear needs exclusion of. Select the single best answer.","options":["Growing pains","Migraine","Septic arthritis","Bursitis"],"answer":2,"explanation":"Septic arthritis can rapidly damage cartilage and requires urgent assessment.","pearl":"Septic arthritis can rapidly damage cartilage and requires urgent assessment.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P117"},{"topic":"Practice · Paediatrics","question":"During an overnight shift, you are consulted about this case. An infant with SVT has poor perfusion and hypotension. Immediate treatment. Select the single best answer.","options":["Synchronized cardioversion","Carotid massage","Oral digoxin","Observation"],"answer":0,"explanation":"Unstable paediatric SVT warrants synchronized electrical cardioversion.","pearl":"Unstable paediatric SVT warrants synchronized electrical cardioversion.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P118"},{"topic":"Practice · Paediatrics","question":"During a busy ED shift, you are asked to review the following case. A child with bronchiolitis has SpO2 87% and increased work of breathing. Best initial care. Select the single best answer.","options":["Oxygen and supportive management","Routine steroids","Routine antibiotics","Routine salbutamol"],"answer":0,"explanation":"Bronchiolitis management is supportive; oxygen is appropriate for significant hypoxaemia.","pearl":"Bronchiolitis management is supportive; oxygen is appropriate for significant hypoxaemia.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P119"},{"topic":"Practice · Paediatrics","question":"At the resuscitation bay handover, the team describes this presentation: A child has a brief generalised febrile seizure, full recovery and normal examination. Next. Select the single best answer.","options":["Reassurance and assess fever source","Chronic antiepileptic therapy","Routine LP for all","Routine CT brain"],"answer":0,"explanation":"Simple febrile seizures generally do not require routine imaging or anticonvulsants.","pearl":"Simple febrile seizures generally do not require routine imaging or anticonvulsants.","reference":"RCH Melbourne clinical practice guidelines","source":"Original FACEM-style practice","id":"P120"},{"topic":"Practice · Trauma","question":"You are the senior emergency physician reviewing a patient. An unstable blunt trauma patient has free intraperitoneal fluid on FAST. Next. Select the single best answer.","options":["Observation","CT before any intervention","Oral tranexamic acid","Urgent operative haemorrhage control"],"answer":3,"explanation":"Unstable trauma with positive FAST needs immediate source control.","pearl":"Unstable trauma with positive FAST needs immediate source control.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P121"},{"topic":"Practice · Trauma","question":"A registrar requests your advice about the following presentation. A pelvic fracture patient is shocked. Where should the pelvic binder sit. Select the single best answer.","options":["Over greater trochanters","Across abdomen","Over iliac crests","Around knees"],"answer":0,"explanation":"Binders reduce pelvic volume most effectively over the greater trochanters.","pearl":"Binders reduce pelvic volume most effectively over the greater trochanters.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P122"},{"topic":"Practice · Trauma","question":"At an ED clinical decision point, consider this scenario: A penetrating chest injury patient is shocked with pericardial fluid on ultrasound. Priority. Select the single best answer.","options":["Diuresis","Outpatient echo","Beta blockade","Urgent surgical management of tamponade"],"answer":3,"explanation":"Penetrating traumatic tamponade requires urgent surgical source control.","pearl":"Penetrating traumatic tamponade requires urgent surgical source control.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P123"},{"topic":"Practice · Trauma","question":"You are supervising an acute assessment. A patient with severe TBI has GCS 6 and is hypoxic. First priority. Select the single best answer.","options":["Give oral analgesia","Secure airway while preventing hypotension","Observe without monitoring","Delay until CT"],"answer":1,"explanation":"Preventing secondary brain injury from hypoxia and hypotension is essential.","pearl":"Preventing secondary brain injury from hypoxia and hypotension is essential.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P124"},{"topic":"Practice · Trauma","question":"An ED team is planning the next step for this presentation. A patient with an open tibial fracture has soil contamination. Early management. Select the single best answer.","options":["Immediate ED closure","IV antibiotics, sterile dressing and surgical referral","Repeated manipulation","Delay antibiotics"],"answer":1,"explanation":"Early antibiotics and operative debridement are central to open-fracture care.","pearl":"Early antibiotics and operative debridement are central to open-fracture care.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P125"},{"topic":"Practice · Trauma","question":"During an overnight shift, you are consulted about this case. A patient with a flail chest is hypoxaemic and splinting due to pain. Management. Select the single best answer.","options":["Routine corticosteroids","Effective analgesia and respiratory support","Fluid restriction only","Chest strapping"],"answer":1,"explanation":"Analgesia and respiratory support improve ventilation and prevent complications.","pearl":"Analgesia and respiratory support improve ventilation and prevent complications.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P126"},{"topic":"Practice · Trauma","question":"During a busy ED shift, you are asked to review the following case. A burn patient from an enclosed-space fire develops hoarseness and facial burns. Priority. Select the single best answer.","options":["Discharge if SpO2 normal","Early expert airway assessment","Wait for stridor","Nebulised salbutamol only"],"answer":1,"explanation":"Airway oedema may progress rapidly after inhalation injury.","pearl":"Airway oedema may progress rapidly after inhalation injury.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P127"},{"topic":"Practice · Trauma","question":"At the resuscitation bay handover, the team describes this presentation: A patient with crush injury has K 7.3 and peaked T waves. First cardiac treatment. Select the single best answer.","options":["Diuretic alone","IV calcium","Wait for CK","Oral potassium"],"answer":1,"explanation":"Hyperkalaemic ECG changes warrant immediate IV calcium.","pearl":"Hyperkalaemic ECG changes warrant immediate IV calcium.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P128"},{"topic":"Practice · Trauma","question":"You are the senior emergency physician reviewing a patient. A patient has a rapidly expanding neck haematoma and stridor after blunt injury. Priority. Select the single best answer.","options":["Discharge","CT first regardless of stability","Neck traction","Controlled airway management by experienced team"],"answer":3,"explanation":"Expanding neck haematoma threatens airway patency.","pearl":"Expanding neck haematoma threatens airway patency.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P129"},{"topic":"Practice · Trauma","question":"A registrar requests your advice about the following presentation. A patient has compartment pain out of proportion and pain on passive stretch after tibial fracture. Next. Select the single best answer.","options":["Routine outpatient review","Urgent surgical assessment for fasciotomy","Apply tight cast","Wait for absent pulses"],"answer":1,"explanation":"Acute compartment syndrome is a surgical emergency; pulses may remain present.","pearl":"Acute compartment syndrome is a surgical emergency; pulses may remain present.","reference":"ATLS principles; local major trauma guidelines","source":"Original FACEM-style practice","id":"P130"},{"topic":"Practice · Neurology","question":"At an ED clinical decision point, consider this scenario: A patient with thunderclap headache has a normal CT 16 hours after onset. Next if SAH concern persists. Select the single best answer.","options":["Routine MRI in a month","Discharge unconditionally","EEG","LP or appropriate vascular investigation"],"answer":3,"explanation":"A delayed negative CT does not reliably exclude SAH in all patients.","pearl":"A delayed negative CT does not reliably exclude SAH in all patients.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P131"},{"topic":"Practice · Neurology","question":"You are supervising an acute assessment. A patient has convulsed continuously for 8 minutes. First-line drug class. Select the single best answer.","options":["Benzodiazepine","Phenytoin first","Propofol without airway plan","Valproate only"],"answer":0,"explanation":"Status epilepticus needs immediate adequate-dose benzodiazepine therapy.","pearl":"Status epilepticus needs immediate adequate-dose benzodiazepine therapy.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P132"},{"topic":"Practice · Neurology","question":"An ED team is planning the next step for this presentation. A patient with acute vestibular syndrome cannot stand and has severe truncal ataxia. Exclude. Select the single best answer.","options":["Otitis externa","Posterior circulation stroke","Simple BPPV","Anxiety"],"answer":1,"explanation":"Severe truncal ataxia is a central neurological red flag.","pearl":"Severe truncal ataxia is a central neurological red flag.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P133"},{"topic":"Practice · Neurology","question":"During an overnight shift, you are consulted about this case. A patient with warfarin-related intracerebral haemorrhage has INR 4.0. Urgent reversal. Select the single best answer.","options":["Oral vitamin K only","Protamine","No reversal","Four-factor PCC plus IV vitamin K"],"answer":3,"explanation":"PCC rapidly reverses warfarin while IV vitamin K sustains correction.","pearl":"PCC rapidly reverses warfarin while IV vitamin K sustains correction.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P134"},{"topic":"Practice · Neurology","question":"During a busy ED shift, you are asked to review the following case. A patient with ascending weakness, areflexia and declining vital capacity has likely. Select the single best answer.","options":["Guillain–Barré syndrome","Multiple sclerosis relapse","Bell palsy","Stroke"],"answer":0,"explanation":"GBS may cause respiratory failure; serial respiratory measurements are essential.","pearl":"GBS may cause respiratory failure; serial respiratory measurements are essential.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P135"},{"topic":"Practice · Neurology","question":"At the resuscitation bay handover, the team describes this presentation: A patient has fluctuating ptosis, bulbar weakness and respiratory distress. Concern. Select the single best answer.","options":["BPPV","Migraine","Peripheral neuropathy only","Myasthenic crisis"],"answer":3,"explanation":"Myasthenic crisis requires close respiratory assessment and critical care support.","pearl":"Myasthenic crisis requires close respiratory assessment and critical care support.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P136"},{"topic":"Practice · Neurology","question":"You are the senior emergency physician reviewing a patient. A patient has fever, altered behaviour and focal seizures. Empiric antiviral. Select the single best answer.","options":["Oseltamivir","IV aciclovir","Metronidazole","Fluconazole"],"answer":1,"explanation":"Treat suspected HSV encephalitis promptly with IV aciclovir.","pearl":"Treat suspected HSV encephalitis promptly with IV aciclovir.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P137"},{"topic":"Practice · Neurology","question":"A registrar requests your advice about the following presentation. A patient has back pain, saddle anaesthesia and urinary retention. Investigation. Select the single best answer.","options":["Outpatient nerve conduction study","Routine lumbar X-ray","No imaging","Urgent MRI spine"],"answer":3,"explanation":"Cauda equina syndrome requires urgent MRI and spinal assessment.","pearl":"Cauda equina syndrome requires urgent MRI and spinal assessment.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P138"},{"topic":"Practice · Neurology","question":"At an ED clinical decision point, consider this scenario: A patient has disabling ischaemic stroke at 9 hours with favourable perfusion imaging and LVO. Consider. Select the single best answer.","options":["Mechanical thrombectomy","Immediate carotid endarterectomy","No reperfusion after 6 hours","Routine heparin"],"answer":0,"explanation":"Selected large-vessel strokes benefit from thrombectomy in extended windows.","pearl":"Selected large-vessel strokes benefit from thrombectomy in extended windows.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P139"},{"topic":"Practice · Neurology","question":"You are supervising an acute assessment. A patient with severe headache, papilloedema and focal deficits needs LP. First step. Select the single best answer.","options":["Neuroimaging and assess LP safety","Immediate LP without assessment","EEG only","Discharge"],"answer":0,"explanation":"Focal deficits and signs of raised intracranial pressure require assessment before LP.","pearl":"Focal deficits and signs of raised intracranial pressure require assessment before LP.","reference":"AHA/ASA stroke guidance; local neurology pathways","source":"Original FACEM-style practice","id":"P140"},{"topic":"Practice · Infectious Diseases","question":"An ED team is planning the next step for this presentation. A patient has fever, neck stiffness and confusion; CT will delay LP. Best next. Select the single best answer.","options":["Oral antibiotics","Wait for LP","Observation","Blood cultures then prompt IV antibiotics"],"answer":3,"explanation":"Antibiotics should not be delayed for imaging or lumbar puncture.","pearl":"Antibiotics should not be delayed for imaging or lumbar puncture.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P141"},{"topic":"Practice · Infectious Diseases","question":"During an overnight shift, you are consulted about this case. A patient with severe leg pain, bullae and shock may have necrotising fasciitis. Priority. Select the single best answer.","options":["Urgent surgical exploration","Oral antibiotics alone","Wait for MRI","Topical therapy"],"answer":0,"explanation":"Early surgical debridement is crucial in necrotising soft-tissue infection.","pearl":"Early surgical debridement is crucial in necrotising soft-tissue infection.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P142"},{"topic":"Practice · Infectious Diseases","question":"During a busy ED shift, you are asked to review the following case. A chemotherapy patient has ANC 0.1 and septic shock. Priority. Select the single best answer.","options":["Prompt antipseudomonal IV antibiotics","Oral amoxicillin","Observe","Wait for cultures"],"answer":0,"explanation":"Neutropenic sepsis requires immediate broad-spectrum IV antibiotics.","pearl":"Neutropenic sepsis requires immediate broad-spectrum IV antibiotics.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P143"},{"topic":"Practice · Infectious Diseases","question":"At the resuscitation bay handover, the team describes this presentation: A patient with an infected obstructing ureteric stone is in shock. Essential treatment. Select the single best answer.","options":["Urgent urinary drainage","Observation","Outpatient lithotripsy","Steroids"],"answer":0,"explanation":"Infected obstruction requires immediate source control by stent or nephrostomy.","pearl":"Infected obstruction requires immediate source control by stent or nephrostomy.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P144"},{"topic":"Practice · Infectious Diseases","question":"You are the senior emergency physician reviewing a patient. An IV drug user has fever, back pain and new leg weakness. Urgent test. Select the single best answer.","options":["Outpatient EMG","Plain radiograph alone","MRI spine","D-dimer"],"answer":2,"explanation":"Spinal epidural abscess can rapidly cause irreversible neurological injury.","pearl":"Spinal epidural abscess can rapidly cause irreversible neurological injury.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P145"},{"topic":"Practice · Infectious Diseases","question":"A registrar requests your advice about the following presentation. A diabetic has severe otalgia, ear canal granulation and cranial neuropathy. Suspect. Select the single best answer.","options":["Viral URTI","Necrotising otitis externa","Simple otitis media","BPPV"],"answer":1,"explanation":"Skull-base infection requires urgent specialist treatment.","pearl":"Skull-base infection requires urgent specialist treatment.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P146"},{"topic":"Practice · Infectious Diseases","question":"At an ED clinical decision point, consider this scenario: A patient with recent antibiotics has diarrhoea, shock and toxic megacolon. Likely pathogen. Select the single best answer.","options":["Norovirus only","Clostridioides difficile","Giardia","Influenza"],"answer":1,"explanation":"Fulminant C difficile infection can cause ileus and megacolon.","pearl":"Fulminant C difficile infection can cause ileus and megacolon.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P147"},{"topic":"Practice · Infectious Diseases","question":"You are supervising an acute assessment. A returning traveller from sub-Saharan Africa has fever and confusion. Urgent exclusion. Select the single best answer.","options":["Falciparum malaria","BPPV","Seasonal allergy","Migraine"],"answer":0,"explanation":"Severe malaria is a time-critical diagnosis in febrile returning travellers.","pearl":"Severe malaria is a time-critical diagnosis in febrile returning travellers.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P148"},{"topic":"Practice · Infectious Diseases","question":"An ED team is planning the next step for this presentation. A patient with HIV CD4 35 has meningitis and elevated opening pressure. Key test. Select the single best answer.","options":["Urine dipstick","CSF cryptococcal antigen","Rapid strep test","Monospot"],"answer":1,"explanation":"CSF cryptococcal antigen supports diagnosis; raised pressure requires management.","pearl":"CSF cryptococcal antigen supports diagnosis; raised pressure requires management.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P149"},{"topic":"Practice · Infectious Diseases","question":"During an overnight shift, you are consulted about this case. A stable patient with suspected endocarditis needs antibiotics. What microbiology first. Select the single best answer.","options":["No cultures","Urine culture only","Multiple blood culture sets","Throat swab only"],"answer":2,"explanation":"Obtain multiple blood cultures before antibiotics when clinically safe.","pearl":"Obtain multiple blood cultures before antibiotics when clinically safe.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines","source":"Original FACEM-style practice","id":"P150"},{"topic":"Practice · Obstetrics & Gynaecology","question":"During a busy ED shift, you are asked to review the following case. A pregnant patient has a seizure and severe hypertension. First-line anticonvulsant. Select the single best answer.","options":["Magnesium sulfate","Phenytoin","Valproate","Levetiracetam alone"],"answer":0,"explanation":"Magnesium sulfate is first-line to treat and prevent eclamptic seizures.","pearl":"Magnesium sulfate is first-line to treat and prevent eclamptic seizures.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P151"},{"topic":"Practice · Obstetrics & Gynaecology","question":"At the resuscitation bay handover, the team describes this presentation: A patient has a positive pregnancy test, shock and free intraperitoneal fluid. Priority. Select the single best answer.","options":["Urgent surgery for suspected ruptured ectopic","Serial hCG only","Outpatient methotrexate","Discharge"],"answer":0,"explanation":"Ruptured ectopic pregnancy with shock requires operative management.","pearl":"Ruptured ectopic pregnancy with shock requires operative management.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P152"},{"topic":"Practice · Obstetrics & Gynaecology","question":"You are the senior emergency physician reviewing a patient. A patient has atonic postpartum haemorrhage. First-line uterotonic. Select the single best answer.","options":["Magnesium sulfate","Terbutaline","Oxytocin","Methotrexate"],"answer":2,"explanation":"Oxytocin is first-line for uterine atony alongside haemorrhage resuscitation.","pearl":"Oxytocin is first-line for uterine atony alongside haemorrhage resuscitation.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P153"},{"topic":"Practice · Obstetrics & Gynaecology","question":"A registrar requests your advice about the following presentation. A patient has ovarian torsion symptoms but Doppler flow is preserved. Interpretation. Select the single best answer.","options":["Confirms PID","Torsion is excluded","No follow-up needed","Torsion is not excluded"],"answer":3,"explanation":"Preserved Doppler flow cannot reliably exclude ovarian torsion.","pearl":"Preserved Doppler flow cannot reliably exclude ovarian torsion.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P154"},{"topic":"Practice · Obstetrics & Gynaecology","question":"At an ED clinical decision point, consider this scenario: A third-trimester patient has painless bleeding and unknown placental position. Avoid. Select the single best answer.","options":["Maternal resuscitation","Ultrasound","Fetal monitoring","Digital vaginal examination"],"answer":3,"explanation":"Digital examination may precipitate major bleeding with placenta praevia.","pearl":"Digital examination may precipitate major bleeding with placenta praevia.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P155"},{"topic":"Practice · Obstetrics & Gynaecology","question":"You are supervising an acute assessment. A patient at 33 weeks has BP 185/115, headache and visual changes. Immediate action. Select the single best answer.","options":["Discharge","Wait for labour","ACE inhibitor","Treat severe hypertension and assess pre-eclampsia"],"answer":3,"explanation":"Severe hypertension in pregnancy requires urgent management and obstetric input.","pearl":"Severe hypertension in pregnancy requires urgent management and obstetric input.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P156"},{"topic":"Practice · Obstetrics & Gynaecology","question":"An ED team is planning the next step for this presentation. A postpartum patient bleeds heavily despite a firm uterus. Important cause. Select the single best answer.","options":["Uterine atony only","Hyperemesis","Genital tract trauma","Normal lochia"],"answer":2,"explanation":"Bleeding with a firm uterus suggests lacerations or retained tissue.","pearl":"Bleeding with a firm uterus suggests lacerations or retained tissue.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P157"},{"topic":"Practice · Obstetrics & Gynaecology","question":"During an overnight shift, you are consulted about this case. A pregnant patient has painful vaginal bleeding and a tender rigid uterus. Suspect. Select the single best answer.","options":["Placental abruption","Cervicitis","Normal labour","Placenta praevia only"],"answer":0,"explanation":"Painful bleeding and uterine tenderness support abruption.","pearl":"Painful bleeding and uterine tenderness support abruption.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P158"},{"topic":"Practice · Obstetrics & Gynaecology","question":"During a busy ED shift, you are asked to review the following case. A patient with pelvic pain, fever and cervical motion tenderness needs. Select the single best answer.","options":["Wait for STI results","Steroids alone","Antifungal alone","Empiric antibiotics for PID"],"answer":3,"explanation":"Early empirical PID treatment reduces reproductive complications.","pearl":"Early empirical PID treatment reduces reproductive complications.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P159"},{"topic":"Practice · Obstetrics & Gynaecology","question":"At the resuscitation bay handover, the team describes this presentation: A postpartum patient has a severe headache and focal neurological deficits. Priority. Select the single best answer.","options":["Discharge","Urgent evaluation for cerebral venous thrombosis and other causes","Assume benign PDPH","Caffeine alone"],"answer":1,"explanation":"Postpartum focal neurological deficits are red flags for intracranial pathology.","pearl":"Postpartum focal neurological deficits are red flags for intracranial pathology.","reference":"RANZCOG guidance; local maternity protocols","source":"Original FACEM-style practice","id":"P160"},{"topic":"Practice · Gastroenterology","question":"You are the senior emergency physician reviewing a patient. A patient has haematemesis, shock and suspected variceal bleeding. Initial targeted treatment. Select the single best answer.","options":["Routine thrombolysis","Oral PPI alone","Discharge","Vasoactive therapy and IV antibiotics with resuscitation"],"answer":3,"explanation":"Suspected variceal bleeding requires resuscitation, vasoactive treatment, antibiotics and urgent endoscopy.","pearl":"Suspected variceal bleeding requires resuscitation, vasoactive treatment, antibiotics and urgent endoscopy.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P161"},{"topic":"Practice · Gastroenterology","question":"A registrar requests your advice about the following presentation. A patient has severe epigastric pain, lipase four times normal and gallstones. Initial priority. Select the single best answer.","options":["Discharge","Routine prophylactic antibiotics","Supportive resuscitation and assess biliary obstruction","Immediate ERCP for all"],"answer":2,"explanation":"Acute pancreatitis requires supportive care; ERCP is reserved for obstruction or cholangitis.","pearl":"Acute pancreatitis requires supportive care; ERCP is reserved for obstruction or cholangitis.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P162"},{"topic":"Practice · Gastroenterology","question":"At an ED clinical decision point, consider this scenario: A patient with cirrhosis has ascites, fever and abdominal pain. Diagnostic test. Select the single best answer.","options":["Colonoscopy","HIDA scan","Breath test","Urgent diagnostic paracentesis"],"answer":3,"explanation":"Ascitic fluid cell count and culture diagnose spontaneous bacterial peritonitis.","pearl":"Ascitic fluid cell count and culture diagnose spontaneous bacterial peritonitis.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P163"},{"topic":"Practice · Gastroenterology","question":"You are supervising an acute assessment. A patient with GI bleeding has haemodynamic instability despite resuscitation. Priority. Select the single best answer.","options":["Observation","Outpatient endoscopy","Urgent definitive haemorrhage control","Oral iron only"],"answer":2,"explanation":"Ongoing unstable GI bleeding requires urgent endoscopic or interventional source control.","pearl":"Ongoing unstable GI bleeding requires urgent endoscopic or interventional source control.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P164"},{"topic":"Practice · Gastroenterology","question":"An ED team is planning the next step for this presentation. A patient has severe abdominal pain out of proportion to examination and AF. Concern. Select the single best answer.","options":["Irritable bowel syndrome","Acute mesenteric ischaemia","Viral gastroenteritis","Simple constipation"],"answer":1,"explanation":"Mesenteric ischaemia presents with severe pain and may have initially subtle signs.","pearl":"Mesenteric ischaemia presents with severe pain and may have initially subtle signs.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P165"},{"topic":"Practice · Gastroenterology","question":"During an overnight shift, you are consulted about this case. A patient has cholangitis with shock, jaundice and biliary obstruction. Source control. Select the single best answer.","options":["Observation","Urgent ERCP biliary drainage","Steroids","Elective colonoscopy"],"answer":1,"explanation":"Severe cholangitis requires antibiotics, resuscitation and urgent biliary drainage.","pearl":"Severe cholangitis requires antibiotics, resuscitation and urgent biliary drainage.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P166"},{"topic":"Practice · Gastroenterology","question":"During a busy ED shift, you are asked to review the following case. A patient has peritonitis and free air under diaphragm. Priority. Select the single best answer.","options":["Discharge","Oral laxatives","Routine ultrasound in a week","Urgent surgical evaluation"],"answer":3,"explanation":"Perforated viscus with peritonitis requires urgent surgical management.","pearl":"Perforated viscus with peritonitis requires urgent surgical management.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P167"},{"topic":"Practice · Gastroenterology","question":"At the resuscitation bay handover, the team describes this presentation: A patient with ulcerative colitis has fever, distension and colonic diameter 8 cm. Suspect. Select the single best answer.","options":["Toxic megacolon","Renal colic","Appendicitis","Simple constipation"],"answer":0,"explanation":"Systemic toxicity with colonic dilation suggests toxic megacolon and warrants urgent specialist care.","pearl":"Systemic toxicity with colonic dilation suggests toxic megacolon and warrants urgent specialist care.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P168"},{"topic":"Practice · Gastroenterology","question":"You are the senior emergency physician reviewing a patient. A patient with severe upper GI bleed is taking warfarin and has INR 5.5. Key consideration. Select the single best answer.","options":["Urgent anticoagulant reversal in life-threatening bleeding","Continue warfarin","Delay haemostasis","Give aspirin"],"answer":0,"explanation":"Life-threatening bleeding requires reversal and source control.","pearl":"Life-threatening bleeding requires reversal and source control.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P169"},{"topic":"Practice · Gastroenterology","question":"A registrar requests your advice about the following presentation. A patient has severe pancreatitis with hypotension and organ failure. Disposition. Select the single best answer.","options":["Routine outpatient MRI","Critical care assessment","Oral antibiotics only","Immediate discharge"],"answer":1,"explanation":"Persistent organ failure defines severe pancreatitis and requires intensive support.","pearl":"Persistent organ failure defines severe pancreatitis and requires intensive support.","reference":"Gastroenterology society guidelines; local surgical pathways","source":"Original FACEM-style practice","id":"P170"},{"topic":"Practice · Renal & Metabolic","question":"At an ED clinical decision point, consider this scenario: A patient with DKA has K 2.9 mmol/L before insulin. First step. Select the single best answer.","options":["Discharge","Start insulin immediately at high dose","Give bicarbonate only","Replace potassium before insulin"],"answer":3,"explanation":"Insulin worsens hypokalaemia; potassium should be corrected before insulin when markedly low.","pearl":"Insulin worsens hypokalaemia; potassium should be corrected before insulin when markedly low.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P171"},{"topic":"Practice · Renal & Metabolic","question":"You are supervising an acute assessment. A patient has hypercalcaemia 4.1 mmol/L with confusion and dehydration. Initial treatment. Select the single best answer.","options":["IV isotonic saline with careful reassessment","Calcium supplements","Thiazide diuretic","Fluid restriction"],"answer":0,"explanation":"Severe symptomatic hypercalcaemia requires hydration and targeted calcium-lowering therapy.","pearl":"Severe symptomatic hypercalcaemia requires hydration and targeted calcium-lowering therapy.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P172"},{"topic":"Practice · Renal & Metabolic","question":"An ED team is planning the next step for this presentation. A patient has adrenal crisis with shock, hyponatraemia and hyperkalaemia. Immediate treatment. Select the single best answer.","options":["Insulin alone","Oral prednisolone next week","IV hydrocortisone and isotonic fluid","Wait for cortisol result"],"answer":2,"explanation":"Suspected adrenal crisis is treated immediately with parenteral hydrocortisone and resuscitation.","pearl":"Suspected adrenal crisis is treated immediately with parenteral hydrocortisone and resuscitation.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P173","image":"practice-ecg-hyperk.png","image_note":"Illustrative teaching schematic; not an authentic patient image."},{"topic":"Practice · Renal & Metabolic","question":"During an overnight shift, you are consulted about this case. A patient with uraemia has pericarditis and refractory hyperkalaemia. Definitive treatment. Select the single best answer.","options":["Observation","Oral diuretics only","Urgent dialysis","Routine antibiotics"],"answer":2,"explanation":"Uraemic pericarditis and refractory hyperkalaemia are indications for urgent renal replacement therapy.","pearl":"Uraemic pericarditis and refractory hyperkalaemia are indications for urgent renal replacement therapy.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P174"},{"topic":"Practice · Renal & Metabolic","question":"During a busy ED shift, you are asked to review the following case. A patient has thyroid storm with fever, tachyarrhythmia and altered consciousness. Initial management. Select the single best answer.","options":["Levothyroxine","Multimodal thyroid storm therapy and supportive care","Observation","Insulin only"],"answer":1,"explanation":"Treat with supportive care, beta blockade if safe, antithyroid therapy and glucocorticoids.","pearl":"Treat with supportive care, beta blockade if safe, antithyroid therapy and glucocorticoids.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P175"},{"topic":"Practice · Renal & Metabolic","question":"At the resuscitation bay handover, the team describes this presentation: A patient has myxoedema coma with hypothermia and bradycardia. Treatment. Select the single best answer.","options":["IV thyroid hormone and stress-dose hydrocortisone","Insulin only","Antithyroid medication","Discharge"],"answer":0,"explanation":"Myxoedema coma is life-threatening and requires hormone replacement and supportive care.","pearl":"Myxoedema coma is life-threatening and requires hormone replacement and supportive care.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P176"},{"topic":"Practice · Renal & Metabolic","question":"You are the senior emergency physician reviewing a patient. A patient with HHS has glucose 52 mmol/L and profound dehydration. Initial priority. Select the single best answer.","options":["Oral hypoglycaemic only","Fluid restriction","Immediate high-dose insulin before fluids","Careful fluid resuscitation and electrolyte assessment"],"answer":3,"explanation":"HHS treatment begins with fluids and electrolyte management; insulin is introduced carefully.","pearl":"HHS treatment begins with fluids and electrolyte management; insulin is introduced carefully.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P177"},{"topic":"Practice · Renal & Metabolic","question":"A registrar requests your advice about the following presentation. A patient with severe rhabdomyolysis has rising creatinine and dark urine. Main early intervention. Select the single best answer.","options":["Isotonic IV fluids with monitoring","Fluid restriction","Routine urine acidification for all","NSAIDs"],"answer":0,"explanation":"Early fluids and electrolyte monitoring are key to preventing renal complications.","pearl":"Early fluids and electrolyte monitoring are key to preventing renal complications.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P178"},{"topic":"Practice · Renal & Metabolic","question":"At an ED clinical decision point, consider this scenario: A patient with profound hypophosphataemia develops respiratory weakness. Treatment. Select the single best answer.","options":["Routine diuretics","Carefully monitored phosphate replacement","Restrict phosphate","Calcium only"],"answer":1,"explanation":"Severe symptomatic hypophosphataemia warrants replacement with monitoring for complications.","pearl":"Severe symptomatic hypophosphataemia warrants replacement with monitoring for complications.","reference":"KDIGO guidance; local metabolic emergency protocols","source":"Original FACEM-style practice","id":"P179"},{"topic":"Practice · ENT & Ophthalmology","question":"You are supervising an acute assessment. A patient has painful red eye, halos, mid-dilated pupil and high IOP. Diagnosis. Select the single best answer.","options":["Retinal detachment","Conjunctivitis","Acute angle-closure glaucoma","Blepharitis"],"answer":2,"explanation":"Angle closure is an ophthalmic emergency requiring urgent pressure-lowering therapy.","pearl":"Angle closure is an ophthalmic emergency requiring urgent pressure-lowering therapy.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P180"},{"topic":"Practice · ENT & Ophthalmology","question":"An ED team is planning the next step for this presentation. A patient has sudden painless monocular vision loss and a cherry-red macula. Diagnosis. Select the single best answer.","options":["Conjunctivitis","Central retinal artery occlusion","Corneal abrasion","Optic neuritis"],"answer":1,"explanation":"CRAO is an ocular stroke requiring urgent stroke-pathway evaluation.","pearl":"CRAO is an ocular stroke requiring urgent stroke-pathway evaluation.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P181"},{"topic":"Practice · ENT & Ophthalmology","question":"During an overnight shift, you are consulted about this case. A patient with contact lens use has a painful red eye and corneal infiltrate. Concern. Select the single best answer.","options":["Migraine","Microbial keratitis","Dry eye only","Simple allergic conjunctivitis"],"answer":1,"explanation":"Contact lens-associated keratitis can threaten vision and needs urgent ophthalmology input.","pearl":"Contact lens-associated keratitis can threaten vision and needs urgent ophthalmology input.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P182"},{"topic":"Practice · ENT & Ophthalmology","question":"During a busy ED shift, you are asked to review the following case. A patient has proptosis, fever and painful restricted eye movements. Diagnosis. Select the single best answer.","options":["Conjunctivitis","BPPV","Preseptal cellulitis only","Orbital cellulitis"],"answer":3,"explanation":"Orbital signs suggest post-septal infection and require urgent imaging and IV antibiotics.","pearl":"Orbital signs suggest post-septal infection and require urgent imaging and IV antibiotics.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P183"},{"topic":"Practice · ENT & Ophthalmology","question":"At the resuscitation bay handover, the team describes this presentation: A patient has sudden sensorineural hearing loss over 24 hours. Management. Select the single best answer.","options":["Antihistamine only","Wait six months","Routine wax removal","Urgent ENT assessment and early corticosteroid consideration"],"answer":3,"explanation":"Sudden sensorineural loss is time sensitive and warrants prompt specialist assessment.","pearl":"Sudden sensorineural loss is time sensitive and warrants prompt specialist assessment.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P184"},{"topic":"Practice · ENT & Ophthalmology","question":"You are the senior emergency physician reviewing a patient. A patient has fever, drooling, muffled voice and tripod positioning. Priority. Select the single best answer.","options":["Force oropharyngeal examination","Discharge","Send unescorted for CT","Keep calm and arrange expert airway team"],"answer":3,"explanation":"Suspected epiglottitis can deteriorate rapidly; avoid provoking airway obstruction.","pearl":"Suspected epiglottitis can deteriorate rapidly; avoid provoking airway obstruction.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P185"},{"topic":"Practice · ENT & Ophthalmology","question":"A registrar requests your advice about the following presentation. A patient with peritonsillar abscess has trismus and uvular deviation. Management. Select the single best answer.","options":["Observe without review","Immediate tonsillectomy for all","Drainage assessment plus antibiotics","Routine antivirals only"],"answer":2,"explanation":"Quinsy often requires drainage and antimicrobial treatment with airway assessment.","pearl":"Quinsy often requires drainage and antimicrobial treatment with airway assessment.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P186"},{"topic":"Practice · ENT & Ophthalmology","question":"At an ED clinical decision point, consider this scenario: A patient has sudden flashes, floaters and curtain-like visual field loss. Diagnosis. Select the single best answer.","options":["Retinal detachment","Uveitis","Acute glaucoma","Conjunctivitis"],"answer":0,"explanation":"Retinal detachment warrants urgent ophthalmological evaluation.","pearl":"Retinal detachment warrants urgent ophthalmological evaluation.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P187"},{"topic":"Practice · ENT & Ophthalmology","question":"You are supervising an acute assessment. A patient with posterior epistaxis remains unstable despite anterior packing. Next. Select the single best answer.","options":["Routine CT in a month","Oral antihistamine","Discharge","Resuscitate and urgent ENT haemorrhage control"],"answer":3,"explanation":"Uncontrolled posterior epistaxis may need specialist packing, embolisation or surgery.","pearl":"Uncontrolled posterior epistaxis may need specialist packing, embolisation or surgery.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P188"},{"topic":"Practice · ENT & Ophthalmology","question":"An ED team is planning the next step for this presentation. A patient has painful swollen ear after piercing through cartilage. Common concern. Select the single best answer.","options":["Cerumen impaction","Perichondritis requiring antipseudomonal assessment","Otitis media","Mastoiditis only"],"answer":1,"explanation":"Cartilage piercing infections can involve Pseudomonas and cause deformity.","pearl":"Cartilage piercing infections can involve Pseudomonas and cause deformity.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols","source":"Original FACEM-style practice","id":"P189"},{"topic":"Practice · Psychiatry & Other","question":"During an overnight shift, you are consulted about this case. A patient on antipsychotics has fever, rigidity, autonomic instability and high CK. Diagnosis. Select the single best answer.","options":["Simple anxiety","Opioid withdrawal","Neuroleptic malignant syndrome","Serotonin syndrome"],"answer":2,"explanation":"NMS causes severe rigidity and hyperthermia following dopamine blockade.","pearl":"NMS causes severe rigidity and hyperthermia following dopamine blockade.","reference":"Local emergency mental health and specialty guidelines","source":"Original FACEM-style practice","id":"P190"},{"topic":"Practice · Psychiatry & Other","question":"During a busy ED shift, you are asked to review the following case. A severely agitated patient is hyperthermic and acidotic after stimulant use. Priority. Select the single best answer.","options":["Beta blocker as sole treatment","Physical restraint alone","Rapid sedation, cooling and supportive resuscitation","Discharge"],"answer":2,"explanation":"Stimulant toxicity can cause hyperthermia and rhabdomyolysis; supportive control is urgent.","pearl":"Stimulant toxicity can cause hyperthermia and rhabdomyolysis; supportive control is urgent.","reference":"Local emergency mental health and specialty guidelines","source":"Original FACEM-style practice","id":"P191"},{"topic":"Practice · Psychiatry & Other","question":"At the resuscitation bay handover, the team describes this presentation: A patient with alcohol dependence has tremor, tachycardia and hallucinations after cessation. Treatment. Select the single best answer.","options":["Benzodiazepine-based withdrawal management","Flumazenil","Discharge","Antipsychotic alone"],"answer":0,"explanation":"Benzodiazepines are first-line for significant alcohol withdrawal; give thiamine when indicated.","pearl":"Benzodiazepines are first-line for significant alcohol withdrawal; give thiamine when indicated.","reference":"Local emergency mental health and specialty guidelines","source":"Original FACEM-style practice","id":"P192"},{"topic":"Practice · Psychiatry & Other","question":"You are the senior emergency physician reviewing a patient. A patient with severe agitation and confusion has a fluctuating level of attention. Diagnosis. Select the single best answer.","options":["Primary psychosis always","Dementia only","Delirium","Malingering"],"answer":2,"explanation":"Acute fluctuating inattention suggests delirium and mandates medical assessment.","pearl":"Acute fluctuating inattention suggests delirium and mandates medical assessment.","reference":"Local emergency mental health and specialty guidelines","source":"Original FACEM-style practice","id":"P193"},{"topic":"Practice · Psychiatry & Other","question":"A registrar requests your advice about the following presentation. A patient presents after intentional overdose and denies current suicidal ideation. Next. Select the single best answer.","options":["Comprehensive psychosocial risk assessment after medical stabilisation","No collateral history","Discharge solely on denial","Avoid safety planning"],"answer":0,"explanation":"Risk assessment must consider circumstances, history, collateral and supports.","pearl":"Risk assessment must consider circumstances, history, collateral and supports.","reference":"Local emergency mental health and specialty guidelines","source":"Original FACEM-style practice","id":"P194"},{"topic":"Practice · Psychiatry & Other","question":"At an ED clinical decision point, consider this scenario: A patient with carbon monoxide exposure has headache and confusion but normal pulse oximetry. Why. Select the single best answer.","options":["Pulse oximetry cannot distinguish oxyhaemoglobin from carboxyhaemoglobin","Only anaemia matters","Oximeter is always broken","CO does not cause hypoxia"],"answer":0,"explanation":"Conventional pulse oximetry can be falsely reassuring in CO poisoning.","pearl":"Conventional pulse oximetry can be falsely reassuring in CO poisoning.","reference":"Local emergency mental health and specialty guidelines","source":"Original FACEM-style practice","id":"P195"},{"topic":"Practice · Psychiatry & Other","question":"You are supervising an acute assessment. A patient with acute limb ischaemia has pain, pallor and absent pulses. Priority. Select the single best answer.","options":["Discharge","Routine outpatient ultrasound","Immediate vascular consultation and anticoagulation if appropriate","Compression bandage"],"answer":2,"explanation":"Acute limb ischaemia is time critical and needs urgent vascular management.","pearl":"Acute limb ischaemia is time critical and needs urgent vascular management.","reference":"Local emergency mental health and specialty guidelines","source":"Original FACEM-style practice","id":"P196"},{"topic":"Practice · Psychiatry & Other","question":"An ED team is planning the next step for this presentation. A patient with septic arthritis of the knee has fever and a large effusion. Diagnostic test. Select the single best answer.","options":["Urgent joint aspiration","Serum urate only","Wait for blood cultures","Plain radiograph alone"],"answer":0,"explanation":"Synovial analysis and culture are key; antibiotics and drainage follow promptly.","pearl":"Synovial analysis and culture are key; antibiotics and drainage follow promptly.","reference":"Local emergency mental health and specialty guidelines","source":"Original FACEM-style practice","id":"P197"},{"id":"P198","source":"Original FACEM-style practice","topic":"Practice · Cardiology","question":"A 71-year-old with exertional dyspnoea has a regular ventricular rate of 150/min. The accompanying rhythm strip demonstrates repetitive flutter waves between QRS complexes. Which rhythm is most likely?","options":["Atrial flutter with 2:1 atrioventricular conduction","Sinus tachycardia with normal P waves","Ventricular fibrillation","Complete heart block"],"answer":0,"explanation":"Atrial flutter commonly has an atrial rate near 300/min with 2:1 AV conduction producing a ventricular rate around 150/min. Flutter waves can be obscured in the QRS or T wave.","pearl":"A very regular rate near 150/min should prompt consideration of 2:1 atrial flutter.","reference":"ESC supraventricular tachycardia guidance","image":"practice-ecg-flutter.png","image_note":"Illustrative teaching schematic; not an authentic patient ECG."},{"id":"P199","source":"Original FACEM-style practice","topic":"Practice · Cardiology","question":"A 64-year-old presents with palpitations. The rhythm strip shown demonstrates regular narrow-complex tachycardia at approximately 150/min. Vagal manoeuvres are unsuccessful and the patient is haemodynamically stable. Which is the most appropriate next intervention?","options":["IV adenosine under monitoring","Immediate IV verapamil in all circumstances","Unmonitored discharge","IV atropine"],"answer":0,"explanation":"For a stable regular narrow-complex SVT, monitored adenosine is a reasonable next step after vagal manoeuvres, after checking contraindications and rhythm interpretation.","pearl":"Always distinguish regular narrow-complex SVT from pre-excited AF before AV nodal blockade.","reference":"ANZCOR peri-arrest arrhythmia guidance","image":"practice-ecg-svt.png","image_note":"Illustrative teaching schematic; not an authentic patient ECG."},{"id":"P200","source":"Original FACEM-style practice","topic":"Practice · Trauma","question":"A 22-year-old cyclist is briefly unconscious after head trauma, wakes, then develops a falling GCS and a unilateral dilated pupil. The accompanying schematic shows a biconvex extra-axial collection. What is the most appropriate immediate management?","options":["Urgent neurosurgical consultation, resuscitation and evacuation planning","Observe for six hours before referral","Perform lumbar puncture","Commence therapeutic anticoagulation"],"answer":0,"explanation":"A rapidly deteriorating patient with a suspected epidural haematoma requires immediate resuscitation and urgent neurosurgical intervention. Do not delay for serial routine observation.","pearl":"A lucid interval followed by deterioration is a classic, but not universal, epidural haematoma presentation.","reference":"Major trauma and neurotrauma guidance","image":"practice-ct-epidural.png","image_note":"Illustrative teaching schematic; not an authentic patient CT."}];
